window.__EBT=window.__EBT||{};window.__EBT["ro"]=window.__EBT["ro"]||{};window.__EBT["ro"]["Isa"]=[[1,[[1,"Vedenia lui Isaia, fiul lui Amot, pe care a văzut-o despre Iuda și Ierusalim, în zilele lui Ozia, Iotam, Ahaz și Ezechia, împărații lui Iuda."],[2,"Auzi, ceruri,"],[3,"Bouul își cunoaște stăpânul,"],[4,"Ah națiune păcătoasă,"],[5,"De ce ar trebui să fii bătut mai mult,"],[6,"De la talpa piciorului până la cap, nu este sănătos în ea,"],[7,"Țara ta este pustie."],[8,"Fiica Sionului este lăsată ca un adăpost într-o vie,"],[9,"Dacă Domnul armatelor nu ne-a lăsat o rămășiță foarte mică,"],[10,"Ascultați cuvântul Domnului, domnitorilor Sodomei!"],[11,"„Care sunt pentru mine mulțimea jertfelor tale?”, zice Domnul."],[12,"Când vii să arăți înaintea mea,"],[13,"Nu mai aduceți ofrande deșarte."],[14,"Sufletul meu urăște lunile tale noi și sărbătorile tale stabilite."],[15,"Când vei întinde mâinile, îmi voi ascunde ochii de tine."],[16,"Spălați-vă. Fă-te curat."],[17,"Învață să faci bine."],[18,"„Veniți acum și să discutăm împreună”, zice Domnul:"],[19,"Dacă ești dispus și ascultător,"],[20,"dar dacă refuzi și vei răzvrăti, vei fi mistuit de sabie;"],[21,"Cât de credincios a devenit o prostituată!"],[22,"Argintul tău a devenit zgură,"],[23,"Prinții tăi sunt răzvrătiți și tovarăși ai hoților."],[24,"De aceea Domnul, Domnul armatelor,"],[25,"Îmi voi întoarce mâna asupra ta,"],[26,"Îți voi restabili judecătorii ca la început,"],[27,"Sionul va fi răscumpărat cu dreptate,"],[28,"Dar nimicirea fărădelegilor și a păcătoșilor va fi împreună,"],[29,"Căci le va fi rușine de stejarii pe care i-ai dorit,"],[30,"Căci vei fi ca un stejar a cărui frunze se stinge,"],[31,"Cei puternici vor fi ca tinerul,"]]],[2,[[1,"Iată ce a văzut Isaia, fiul lui Amoț, despre Iuda și Ierusalim."],[2,"Se va întâmpla în zilele din urmă, că muntele Casei Domnului va fi întemeiat pe vârful munților,"],[3,"Multe popoare vor merge și vor spune:"],[4,"El va judeca între popoare,"],[5,"Casa lui Iacov, vino și să umblăm în lumina Domnului."],[6,"Căci ai părăsit poporul tău, casa lui Iacov,"],[7,"Țara lor este plină de argint și aur,"],[8,"Și țara lor este plină de idoli."],[9,"Omul este coborât,"],[10,"Intră în stâncă,"],[11,"Privirile înalte ale omului vor fi coborâte,"],[12,"Căci va fi o zi a Domnului oștirilor pentru toți cei mândri și trufași,"],[13,"pentru toți cedrii Libanului, care sunt înalți și înalți,"],[14,"pentru toți munții înalți,"],[15,"pentru fiecare turn înalt,"],[16,"pentru toate corăbiile din Tarsis,"],[17,"Înălțimea omului va fi plecată,"],[18,"Idolii vor trece cu totul."],[19,"Oamenii vor intra în peșterile stâncilor,"],[20,"În ziua aceea, oamenii își vor arunca idolii de argint"],[21,"a intra în cavernele stâncilor,"],[22,"Încetează să te încrezi în om, a cărui suflare este în nări;"]]],[3,[[1,"Căci, iată, Domnul, Domnul armatelor, ia de la Ierusalim și de la Iuda provizii și sprijin,"],[2,"omul puternic,"],[3,"căpitanul de cincizeci,"],[4,"Voi da băieți să fie prinți ai lor,"],[5,"Poporul va fi asuprit,"],[6,"Într-adevăr, omul va prinde pe fratele său în casa tatălui său, zicând:"],[7,"În ziua aceea va striga, zicând: „Nu voi fi vindecător;"],[8,"Căci Ierusalimul este distrus și Iuda a căzut;"],[9,"Expresia fețelor lor mărturisește împotriva lor."],[10,"Spune celor drepți că le va fi bine,"],[11,"Vai de cei răi!"],[12,"Cât despre poporul meu, copiii sunt asupritorii lor,"],[13,"Domnul se ridică să lupte,"],[14,"Domnul va intra la judecată cu bătrânii poporului Său"],[15,"Ce vrei să spui că îmi zdrobești poporul,"],[16,"Mai mult, Domnul a zis: „Pentru că fiicele Sionului sunt îngâmfate,"],[17,"de aceea, Domnul aduce răni pe coroana capului femeilor din Sion,"],[18,"În ziua aceea, Domnul le va lua frumusețea gleznelor, a bentițelor, a colierelor cu semilună,"],[19,"cerceii, brățările, voalurile,"],[20,"coifiile, lanțurile de glezne, cenelele, recipientele de parfum, farmecele,"],[21,"inelele cu sigiliu, inelele din nas,"],[22,"hainele fine, pelerine, mantii, poșete,"],[23,"oglinzile de mână, hainele de in fin, diademele și șalurile."],[24,"Se va întâmpla ca în loc de mirodenii dulci, să fie putreziciune;"],[25,"Oamenii tăi vor cădea prin sabie,"],[26,"Porțile ei se vor tângui și plânge."]]],[4,[[1,"Șapte femei vor prinde un bărbat în ziua aceea și vor zice: „Vom mânca propria noastră pâine și ne vom purta hainele noastre. Doar să ne cheme numele tău. Îndepărtează-ne ocara.”"],[2,"În ziua aceea, mlădița Domnului va fi frumoasă și slăvită, iar rodul țării va fi frumusețea și slava supraviețuitorilor lui Israel."],[3,"Se va întâmpla ca cel ce rămâne în Sion și cel care rămâne în Ierusalim să fie numit sfinți, chiar și oricine este scris între cei vii din Ierusalim,"],[4,"când Domnul va fi spălat mizeria fiicelor Sionului și va curăța sângele Ierusalimului dinăuntrul lui, prin duhul dreptății și prin duhul arderii."],[5,"Domnul va face peste tot locuința muntelui Sion și peste adunările ei, un nor și fum ziua și strălucirea unui foc aprins noaptea, căci peste toată slava va fi un baldachin."],[6,"Va fi un foișor pentru umbră în timpul zilei de căldură, și pentru adăpost și pentru adăpost de furtună și de ploaie."]]],[5,[[1,"Lasă-mă să cânt pentru iubitul meu un cântec al iubitului meu despre via lui."],[2,"L-a dezgropat,"],[3,"„Acum, locuitori ai Ierusalimului și bărbați ai lui Iuda,"],[4,"Ce s-ar fi putut face mai mult viei mele, ceea ce eu nu am făcut în ea?"],[5,"Acum vă voi spune ce voi face viei mele."],[6,"O voi pune un pustiu."],[7,"Căci via DOMNULUI Oștilor este casa lui Israel,"],[8,"Vai de cei care se unesc casă în casă,"],[9,"În urechile mele, Domnul armatelor spune: „Cu siguranță multe case vor fi pustii,"],[10,"Pentru zece acri de vie va da o baie,"],[11,"Vai de cei care se trezesc dis-de-dimineață, ca să urmeze băuturi tari,"],[12,"Harpa, lira, tamburina și flaut, cu vin, sunt la sărbătorile lor;"],[13,"De aceea poporul meu intră în robie din lipsă de cunoștințe."],[14,"De aceea, Sheolul și-a mărit dorința,"],[15,"Deci omul este coborât,"],[16,"dar Domnul armatelor este înălțat în dreptate,"],[17,"Atunci mieii vor pășuna ca în pășunea lor,"],[18,"Vai de cei care trag nelegiuirea cu corzile minciuni,"],[19,"care spun: „Să se grăbească, să-și grăbească lucrarea, ca să o vedem;"],[20,"Vai de cei care numesc răul bun și binele rău;"],[21,"Vai de cei care sunt înțelepți în ochii lor,"],[22,"Vai de cei care sunt puternici să bea vin,"],[23,"care îl achită pe vinovați pentru mită,"],[24,"De aceea, precum limba de foc mistuie miriștea,"],[25,"De aceea mânia Domnului se aprinde împotriva poporului Său,"],[26,"El va ridica un steag către neamurile de departe,"],[27,"Nimeni nu se va obosi și nu se va poticni printre ei;"],[28,"ale căror săgeți sunt ascuțite,"],[29,"Buletul lor va fi ca o leoaică."],[30,"Ei vor răcni împotriva lor în ziua aceea ca vuietul mării."]]],[6,[[1,"În anul în care a murit regele Ozia, l-am văzut pe Domnul stând pe un tron ​​înalt și înălțat; iar trena lui a umplut templul."],[2,"Deasupra lui stăteau serafimii. Fiecare avea șase aripi. Cu doi și-a acoperit fața. Cu doi și-a acoperit picioarele. Cu doi a zburat."],[3,"Unul a chemat pe altul și a spus:"],[4,"Fundațiile pragurilor s-au zguduit de glasul celui care a strigat și casa s-a umplut de fum."],[5,"Atunci am zis: „Vai de mine, căci sunt nimicit, pentru că sunt un om cu buze necurate și locuiesc în mijlocul unui popor cu buze necurate, căci ochii mei l-au văzut pe Împăratul, Domnul oștirilor!”"],[6,"Atunci unul dintre serafimi a zburat la mine, având în mână un cărbune aprins, pe care îl luase cu cleștele de pe altar."],[7,"Mi-a atins gura cu ea și a zis: „Iată, aceasta s-a atins de buzele tale, nelegiuirea ți-a fost luată și păcatul ți-a fost iertat”."],[8,"Am auzit glasul Domnului, zicând: „Pe cine să trimit și cine va merge pentru noi?”"],[9,"El a spus: „Du-te și spune-i acestui popor:"],[10,"Îngrașă inima acestui popor."],[11,"Apoi am spus: „Doamne, până când?”"],[12,"și Domnul a îndepărtat oamenii pe oameni,"],[13,"Dacă a mai rămas o zecime în el,"]]],[7,[[1,"În zilele lui Ahaz, fiul lui Iotam, fiul lui Ozia, regele lui Iuda, Rețin, împăratul Siriei, și Pecah, fiul lui Remalia, împăratul lui Israel, s-au suit la Ierusalim să lupte împotriva lui, dar nu au putut să-l învingă."],[2,"Casei lui David i s-a spus: „Siria este aliată cu Efraim”. Inima lui tremura, și inima poporului său, precum copacii pădurii tremură de vânt."],[3,"Atunci Domnul a zis lui Isaia: „Ieși acum în întâmpinarea lui Ahaz, tu și fiul tău Șearjașub, la capătul canalului iazului de sus, pe drumul câmpului plinului."],[4,"Spune-i: „Fii atent și păstrează-ți calmul. Nu-ți fie teamă și nici să nu-ți slăbească inima din cauza acestor două cozi de făclii fumegătoare, pentru mânia aprigă a Reținului și a Siriei și a fiului lui Remalia."],[5,"Pentru că Siria, Efraim și fiul lui Remalia au plănuit rău împotriva ta, spunând:"],[6,"„Să ne urcăm împotriva lui Iuda, să-l sfărâm și să-l împărțim între noi și să punem în ea un rege, chiar fiul lui Tabeel.”"],[7,"Iată ce spune Domnul Iehova: „Nu va rezista, nici nu se va întâmpla”."],[8,"Căci capul Siriei este Damasc și capul Damascului este Rețin. Peste șaizeci și cinci de ani, Efraim va fi zdrobit și nu va mai fi un popor."],[9,"Capul lui Efraim este Samaria, iar capul Samariei este fiul lui Remalia. Dacă nu vei crede, cu siguranță nu vei fi întărit.”"],[10,"Domnul a vorbit din nou lui Ahaz, zicând:"],[11,"„Cereți un semn de la Domnul Dumnezeul vostru; cereți-l fie în adânc, fie în înălțimea de sus.”"],[12,"Dar Ahaz a zis: „Nu voi cere, nu voi ispiti pe Domnul”."],[13,"El a zis: „Ascultați acum, casa lui David: nu vă este suficient să încercați răbdarea oamenilor, ca să încercați și răbdarea Dumnezeului meu?"],[14,"De aceea Domnul însuși vă va da un semn. Iată, fecioara va rămâne însărcinată și va naște un fiu și îi va pune numele Emanuel."],[15,"El va mânca unt și miere când știe să refuze răul și să aleagă binele."],[16,"Căci înainte ca copilul să știe să refuze răul și să aleagă binele, țara ai cărei doi împărați îi detestați va fi părăsită."],[17,"Domnul va aduce asupra ta, asupra poporului tău și asupra casei tatălui tău zile care nu au venit, din ziua în care Efraim a plecat din Iuda, regele Asiriei."],[18,"În ziua aceea, Domnul va fluiera pentru musca care este la marginea râurilor Egiptului și pentru albina care este în țara Asiriei."],[19,"Ei vor veni și toți se vor odihni în văile pustii, în crăpăturile stâncilor, în toate gardurile de spini și pe toate pășunile."],[20,"În ziua aceea, Domnul va rade cu un brici care este închiriat în părțile de dincolo de râu, chiar și cu regele Asiriei, capul și părul picioarelor; și va mistui și barba."],[21,"Se va întâmpla în ziua aceea că omul va ține în viață o vacă tânără și două oi."],[22,"Se va întâmpla că, din pricina abundenței de lapte pe care îl vor da, el va mânca unt, căci toți vor mânca unt și miere care au rămas în pământ."],[23,"Se va întâmpla în ziua aceea că fiecare loc unde erau o mie de viță de vie care valorează o mie de sicli de argint, va fi pentru mărăcini și spini."],[24,"Oamenii vor merge acolo cu săgeți și cu arc, pentru că toată țara va fi mărăcini și spini."],[25,"Toate dealurile care au fost cultivate cu sapa, nu veți veni acolo de teamă de mărăcini și spini; dar va fi pentru trimiterea boilor și pentru oile pe care să le calce”."]]],[8,[[1,"Domnul mi-a zis: „Ia o tăbliță mare și scrie pe ea cu pixul unui bărbat: „Pentru Maher Shalal Hash Baz”;"],[2,"și voi lua pentru mine martori credincioși să depună mărturie: preotul Urie și Zaharia, fiul lui Ieberechia.”"],[3,"M-am dus la prooroci și ea a rămas însărcinată și a născut un fiu. Atunci Domnul mi-a zis: „Pune-i numele „Maher Şalal Hash Baz”."],[4,"Căci înainte ca copilul să știe să spună: „Tatăl meu” și „Mama mea”, bogățiile Damascului și prada Samariei vor fi luate de regele Asiriei.”"],[5,"Domnul mi-a vorbit din nou, zicând:"],[6,"„Pentru că acest popor a refuzat apele din Siloa care merg încet și se bucură de Rețin și de fiul lui Remalia;"],[7,"acum de aceea, iată, Domnul aduce asupra lor puternicele ape ale râului: regele Asiriei și toată slava lui. Va trece peste toate canalele sale și va trece peste toate malurile sale."],[8,"Va mătura mai departe în Iuda. Se va revărsa și va trece. Va ajunge până la gât. Întinderea aripilor lui va umple lățimea pământului tău, Emanuel."],[9,"Faceți vâlvă, popoare, și fiți rupte în bucăți! Ascultați, toți din țări îndepărtate: îmbrăcați-vă pentru luptă și fiți spulberați! Îmbrăcați-vă pentru luptă și fii spulberat!"],[10,"Luați sfat împreună și va fi nimicit; rostește cuvântul și nu va rezista, căci Dumnezeu este cu noi.”"],[11,"Căci Domnul mi-a spus aceasta cu o mână puternică și m-a poruncit să nu merg pe calea acestui popor, zicând:"],[12,"„Nu numiți conspirație tot ceea ce oamenii ăștia numesc conspirație. Nu vă temeți de amenințările lor și nu fiți terorizați."],[13,"Domnul armatelor este pe care trebuie să-l respectați ca sfânt. El este cel de care trebuie să te temi. El este cel de care trebuie să te temi."],[14,"El va fi un sanctuar, dar pentru ambele case ale lui Israel va fi o piatră de poticnire și o stâncă care le va face să cadă. Pentru poporul Ierusalimului, el va fi o capcană și o cursă."],[15,"Mulți se vor împiedica de ea, vor cădea, vor fi zdrobiți, vor fi prinși în capcană și vor fi prinși.”"],[16,"Încheiați legământul. Pecetluiește legea între ucenicii mei."],[17,"Voi aștepta pe Domnul, care își ascunde fața de casa lui Iacov, și-l voi căuta."],[18,"Iată, eu și copiii pe care mi-a dat Domnul, suntem ca semne și minuni în Israel de la Domnul oștirilor, care locuiește pe muntele Sionului."],[19,"Când îți spun: „Consultăți-vă cu cei care au spirite familiare și cu vrăjitorii, care ciripesc și care mormăie”, nu ar trebui un popor să se sfătuiască cu Dumnezeul lor? Ar trebui să-i consulte pe morți în numele celor vii?"],[20,"Întoarce-te la lege și la legământ! Dacă nu vorbesc după acest cuvânt, cu siguranță nu există dimineață pentru ei."],[21,"Vor trece prin ea, foarte necăjiți și flămânzi. Se va întâmpla ca atunci când le este foame, să-și facă griji și să-și blesteme regele și Dumnezeul lor. Își vor întoarce fețele în sus,"],[22,"apoi priviți spre pământ și vedeți necazul, întunericul și întunericul suferinței. Vor fi împinși în întuneric dens."]]],[9,[[1,"Dar nu va mai fi întuneric pentru ea care era în suferință. În vremurile trecute, el a adus în dispreț țara lui Zabulon și țara lui Neftali; dar în timpul din urmă a făcut-o glorioasă, pe drumul mării, dincolo de Iordan, Galileea neamurilor."],[2,"Oamenii care au umblat în întuneric au văzut o lumină mare."],[3,"Ai înmulțit neamul."],[4,"Pentru că jugul poverii lui și toiagul umărului lui, toiagul asupritorului său, ai rupt ca în ziua lui Madian."],[5,"Căci toată armura omului înarmat în lupta zgomotoasă și hainele tăvălite în sânge, vor fi pentru ardere, combustibil pentru foc."],[6,"Căci ni s-a născut un copil. Un fiu ne este dat; iar guvernul va fi pe umerii lui. Numele Lui va fi numit Sfetnic Minunat, Dumnezeu puternic, Tată veșnic, Prinț al păcii."],[7,"Înmulțirea stăpânirii sale și a păcii nu va avea sfârșit, pe tronul lui David și pe împărăția lui, ca să-l întărească și să-l susțină cu dreptate și cu dreptate de atunci încolo și pentru totdeauna. Rânvna Domnului oștirilor va face aceasta."],[8,"Domnul a trimis un cuvânt în Iacov,"],[9,"Toți oamenii vor ști,"],[10,"„Cărămizile au căzut,"],[11,"De aceea, Domnul va ridica împotriva lui pe vrăjmașii lui Rețin,"],[12,"Sirienii din fata,"],[13,"Dar poporul nu s-a întors la Cel care i-a lovit,"],[14,"De aceea, Domnul va tăia din Israel capul și coada,"],[15,"Bătrânul și omul onorabil este capul,"],[16,"Căci cei care conduc acest popor îi duc în rătăcire;"],[17,"De aceea Domnul nu se va bucura de tinerii lor,"],[18,"Căci răutatea arde ca focul."],[19,"Prin mânia Domnului oștirilor, țara este arsă;"],[20,"Cineva va mânca de-a dreapta și va fi flămând;"],[21,"Manase îl mănâncă pe Efraim și Efraim îl mănâncă pe Manase și împreună vor fi împotriva lui Iuda."]]],[10,[[1,"Vai de cei care decretează decrete nedrepte și de scriitorii care scriu decrete asupritoare"],[2,"să-i lipsesc pe cei nevoiași de dreptate și să-i jefuiesc pe cei săraci din poporul Meu de drepturile lor, ca văduvele să fie prada lor și să-i facă prada pe orfan!"],[3,"Ce vei face în ziua pedepsei și în pustiirea care va veni de departe? La cine vei fugi după ajutor? Unde îți vei lăsa averea?"],[4,"Nu se vor închina decât sub prizonieri,"],[5,"Vai asirian, toiagul mâniei mele, toiagul în a cărui mână este mânia mea!"],[6,"Îl voi trimite împotriva unui neam profan și împotriva poporului care mă mânie îi voi da poruncă să ia prada și să ia prada și să-i calce ca mocirla de pe străzi."],[7,"Cu toate acestea, el nu vrea să spună așa, nici inima lui nu crede așa; dar este în inima lui să nimicească și să nimicească nu puține neamuri."],[8,"Căci el spune: „Nu sunt toți prinții mei regi?"],[9,"Calno nu seamănă cu Carchemish? Nu este Hamat ca Arpad? Nu este Samaria ca Damasc?”"],[10,"După cum mâna mea a găsit împărățiile idolilor, ale căror imagini gravate le depășeau pe cele ale Ierusalimului și ale Samariei,"],[11,"Nu voi face eu, așa cum am făcut Samariei și idolilor ei, Ierusalimului și idolilor ei?"],[12,"De aceea, atunci când Domnul își va împlini toată lucrarea pe muntele Sionului și pe Ierusalim, voi pedepsi rodul inimii mândre voinice a împăratului Asiriei și răbdarea privirilor lui îngâmfate."],[13,"Căci el a spus: „Cu puterea mâinii mele am făcut asta și prin înțelepciunea mea, căci am pricepere. Am îndepărtat hotarele popoarelor și le-am jefuit comorile. Ca un om viteaz, le-am doborât stăpânitorii."],[14,"Mâna mea a găsit bogățiile popoarelor ca un cuib, și precum cineva adună ouăle părăsite, am adunat tot pământul. Nu a fost nimeni care să-și miște aripa, sau care să-și fi deschis gura, sau să ciripi.”"],[15,"Ar trebui să se laude un topor împotriva celui care toacă cu ea? Ar trebui un ferăstrău să se înalțe mai presus de cel care vede cu el? Ca și cum un toiag ar trebui să ridice pe cei care o ridică, sau ca și cum un toiag ar trebui să ridice pe cineva care nu este de lemn."],[16,"De aceea, Domnul, Domnul oştirilor, va trimite printre cei grăşi săi slăbiciune; şi sub slava lui se va aprinde o ardere ca focul."],[17,"Lumina lui Israel va fi un foc, iar Sfântul Lui va fi o flacără; și îi va arde și va mistui spinii și mărăcinii într-o singură zi."],[18,"El va mistui slava pădurii sale și a câmpului său roditor, atât sufletul cât și trupul. Va fi ca atunci când un purtător de stindard leșină."],[19,"Rămășița copacilor din pădurea lui va fi puțină, astfel încât un copil să-și poată scrie numărul."],[20,"Se va întâmpla în ziua aceea că rămășița lui Israel și cei care au scăpat din casa lui Iacov nu se vor mai sprijini de cel care i-a lovit, ci se vor sprijini în adevăr pe Domnul, Sfântul lui Israel."],[21,"O rămășiță se va întoarce, chiar și rămășița lui Iacov, la Dumnezeul puternic."],[22,"Căci, deși poporul tău, Israel, este ca nisipul mării, numai o rămășiță din ei se va întoarce. O distrugere este determinată, plină de dreptate."],[23,"Căci Domnul, Domnul oștirilor, va pune capăt deplin și hotărât pe tot pământul."],[24,"De aceea, Domnul, Domnul oștirilor, zice: „Poporul Meu, care locuiește în Sion, nu te teme de Asirian, deși te lovește cu toiagul și își ridică toiagul împotriva ta, așa cum a făcut Egiptul."],[25,"Căci încă foarte puțin și mânia împotriva ta se va împlini și mânia mea se va îndrepta spre nimicirea lui.”"],[26,"Domnul oștirilor va stârni un flagel împotriva lui, ca în măcelul lui Madian la stânca lui Oreb. Toiagul lui va fi deasupra mării și o va ridica așa cum a făcut împotriva Egiptului."],[27,"Se va întâmpla în ziua aceea că povara lui se va îndepărta de pe umărul tău și jugul lui de pe gâtul tău și jugul va fi nimicit din cauza uleiului pentru ungere."],[28,"A venit la Aiath. A trecut prin Migron. La Michmash își depozitează bagajele."],[29,"Au trecut peste trecere. Ei și-au cazat la Gheba. Rama se cutremură. Ghibea lui Saul a fugit."],[30,"Plângi cu glas tare, fiica lui Gallim! Ascultă, Laishah! Sărmanul Anathoth!"],[31,"Madmenah este o fugară. Locuitorii din Gebim fug pentru siguranță."],[32,"Chiar în această zi se va opri la Nob. Își strânge mâna spre muntele fiicei Sionului, dealul Ierusalimului."],[33,"Iată, Domnul, Domnul oștirilor, va tăia crengile cu groază. Cel înalt va fi tăiat, iar cel înalt va fi coborât."],[34,"El va tăia cu fier desișurile pădurii și Libanul va cădea de Cel Puternic."]]],[11,[[1,"Un lăstar va ieși din stocul lui Isai,"],[2,"Duhul Domnului se va odihni peste el:"],[3,"Desfătarea Lui va fi în frica de Domnul."],[4,"dar el va judeca pe săraci cu dreptate,"],[5,"Dreptatea va fi centura din jurul taliei lui,"],[6,"Lupul va trăi cu mielul,"],[7,"Vaca și ursul vor pășuna."],[8,"Copilul care alăptează se va juca lângă gaura unei cobre,"],[9,"Nu vor răni, nici nu vor nimici în tot muntele Meu sfânt;"],[10,"Se va întâmpla în ziua aceea că neamurile vor căuta rădăcina lui Isai, care stă ca steagul popoarelor; iar locul lui de odihnă va fi glorios."],[11,"Se va întâmpla în ziua aceea că Domnul își va pune iarăși mâna a doua oară pentru a recupera rămășița care a rămas din poporul Său din Asiria, din Egipt, din Patros, din Cuș, din Elam, din Sinar, din Hamat și din insulele mării."],[12,"El va înălța un steag pentru neamuri și va aduna pe cei alungați ai lui Israel și va aduna pe cei împrăștiați din Iuda din cele patru colțuri ale pământului."],[13,"Invidia lui Efraim va dispărea și cei ce îl persecută pe Iuda vor fi nimiciți. Efraim nu-l va invidia pe Iuda și Iuda nu-l va persecuta pe Efraim."],[14,"Ei vor zbura pe umerii filistenilor de la apus. Împreună îi vor jefui pe copiii răsăritului. Ei își vor întinde puterea asupra Edomului și Moabului și copiii lui Amon le vor asculta."],[15,"Domnul va nimici cu desăvârşire limba mării Egiptului; și cu vântul lui arzător își va flutura mâna peste râu și îl va despărți în șapte pâraie și va face pe oameni să treacă în sandale."],[16,"Va fi o cale pentru rămășița poporului său din Asiria, așa cum a fost pentru Israel în ziua când a ieșit din țara Egiptului."]]],[12,[[1,"În ziua aceea vei zice: „Îți voi mulțumi, Doamne, căci, deși te-ai mâniat pe mine, mânia Ta s-a abătut și mă mângâi."],[2,"Iată, Dumnezeu este mântuirea mea. Mă voi încrede și nu mă voi teme; căci DOMNUL, DOMNUL, este puterea și cântarea mea; și el a devenit mântuirea mea”."],[3,"De aceea cu bucurie vei scoate apă din fântânile mântuirii."],[4,"În ziua aceea vei zice: „Lăudați Domnului, chemați Numele Lui, vestiți faptele Lui între popoare, vestiți că Numele Lui este înălțat!"],[5,"Cântați Domnului, căci El a făcut lucruri bune! Să fie cunoscut acest lucru pe tot pământul!"],[6,"Strigă și strigă, locuitorul Sionului, căci Sfântul lui Israel este mare între tine!”"]]],[13,[[1,"Povara Babilonului, pe care a văzut-o Isaia, fiul lui Amot."],[2,"Pune un banner pe muntele gol! Ridică-ți vocea la ei! Flutură-ți mâna, ca să intre pe porțile nobililor."],[3,"Le-am poruncit celor consacrați; da, i-am chemat pe oamenii mei puternici pentru mânia mea, chiar și pe cei care se bucură de mândrie."],[4,"Zgomotul unei mulțimi este în munți, ca al unui popor mare; zgomot de zarvă al împărățiilor neamurilor adunate! Domnul armatelor adună armata pentru luptă."],[5,"Ei vin dintr-o țară îndepărtată, de la marginea cerului, chiar DOMNUL și armele mâniei Lui, pentru a nimici toată țara."],[6,"Te plângi, căci ziua Domnului este aproape! Va veni ca o distrugere de la Cel Atotputernic."],[7,"De aceea toate mâinile vor fi slăbite și inima tuturor se va topi."],[8,"Vor fi consternați. Necazurile și durerile îi vor prinde. Vor suferi ca o femeie în travaliu. Se vor privi uimiți unul la altul. Fețele lor vor fi fețe de flăcări."],[9,"Iată că vine ziua Domnului, crudă, cu mânie și mânie aprinsă; ca să facă țara o pustiire și să-i nimicească pe păcătoșii din ea."],[10,"Căci stelele cerului și constelațiile lui nu își vor da lumina. Soarele se va întuneca la stingerea lui, iar luna nu-i va face să strălucească lumina."],[11,"Voi pedepsi lumea pentru răul lor și pe cei răi pentru nelegiuirea lor. Voi face să înceteze aroganța celor mândri și voi smeri aroganța celor groaznici."],[12,"Voi face oamenii mai rari decât aurul fin, chiar o persoană decât aurul curat din Ofir."],[13,"De aceea voi face cerurile să se cutremure și pământul se va zgudui din locul său în mânia Domnului oștirilor și în ziua mâniei Lui aprinse."],[14,"Se va întâmpla ca, asemenea gazelei vânate și ca oile pe care nimeni nu le strânge, fiecare să se întoarcă la propriul popor și să fugă fiecare în țara lui."],[15,"Toți cei care vor fi găsiti vor fi împinși. Toți cei prinși vor cădea de sabie."],[16,"De asemenea, pruncii lor vor fi sfărâmați în bucăți în fața ochilor lor. Casele lor vor fi jefuite, iar soțiile lor vor fi violate."],[17,"Iată, voi stârni împotriva lor pe Medii, care nu prețuiesc argintul și, în ceea ce privește aurul, nu se vor bucura de el."],[18,"Arcurile lor îi vor sfărâma pe tineri; şi nu vor avea milă de rodul pântecelui. Ochii lor nu vor cruța copiii."],[19,"Babilonul, slava împărățiilor, frumusețea mândriei caldeenilor, va fi ca atunci când Dumnezeu a răsturnat Sodoma și Gomora."],[20,"Nu va fi niciodată locuit și nici nu va fi trăit din generație în generație. Arabul nu va ridica cortul acolo, nici păstorii nu-și vor pune turmele acolo jos."],[21,"Dar animalele sălbatice ale pustiului vor zace acolo și casele lor vor fi pline de șacali. Acolo vor locui struții și acolo vor zburda caprele sălbatice."],[22,"Hienele vor plânge în cetățile lor, iar șacalii în palatele plăcute. Timpul ei este aproape să vină și zilele ei nu se vor prelungi."]]],[14,[[1,"Căci Domnul va avea milă de Iacov și va alege totuși pe Israel și-l va așeza în țara lor. Străinul se va uni cu ei și se vor uni cu casa lui Iacov."],[2,"Popoarele îi vor lua și îi vor aduce la locul lor. Casa lui Israel îi va stăpâni în țara Domnului ca slujitori și roabe. Ei îi vor lua ca prizonieri pe cei ai căror robi au fost; și vor stăpâni peste asupritorii lor."],[3,"Se va întâmpla în ziua în care DOMNUL îți va da odihnă de întristarea ta, de necazul tău și de slujirea grea în care ai fost pus să slujești,"],[4,"că vei spune această pildă împotriva împăratului Babilonului și vei spune: „Cum a încetat asupritorul! Cetatea de aur a încetat!”"],[5,"Domnul a spart toiagul celor răi, sceptrul conducătorilor,"],[6,"care a lovit popoarele cu mânie cu o lovitură continuă, care a stăpânit neamurile cu mânie, cu o persecuție pe care nimeni nu a înfrânat-o."],[7,"Întregul pământ este în repaus și este liniștit. Ei izbucnesc în cântec."],[8,"Da, chiparoșii se bucură împreună cu tine, cu cedrii Libanului, spunând: „De când ești smerit, niciun tăietor de lemne nu s-a suit împotriva noastră”."],[9,"Sheolul de dedesubt s-a mutat ca să te întâlnești la venirea ta. Ea trezește spiritele plecate pentru tine, chiar și pe toți conducătorii pământului. Ea a ridicat de pe tronurile lor pe toți împărații popoarelor."],[10,"Toți vor răspunde și vă vor întreba: „Ați devenit și voi la fel de slab ca și noi? Ați devenit ca noi?”"],[11,"Pompa ta este coborâtă în mormânt, cu sunetul instrumentelor tale cu coarde. Virmele sunt întinse sub tine, iar viermii te acoperă."],[12,"Cât ai căzut din cer, strălucitor, fiu al zorilor! Cum ești doborât la pământ, care ai doborât neamurile!"],[13,"Ai spus în inima ta: „Mă voi înălța la cer, îmi voi înălța scaunul de domnie mai presus de stelele lui Dumnezeu, voi ședea pe muntele adunării, în nordul îndepărtat!"],[14,"Voi urca deasupra înălțimii norilor! Mă voi face ca Cel Prea Înalt!”"],[15,"Dar vei fi coborât în ​​mormânt, în adâncul gropii."],[16,"Cei care te văd se vor uita la tine. Ei se vor gândi la tine, zicând: „Este acesta omul care a făcut să se cutremure pământul, care a zguduit împărății,"],[17,"care a făcut lumea ca o pustie și i-a răsturnat cetățile, care nu și-a eliberat prizonierii în casa lor?”"],[18,"Toți împărații neamurilor dorm în slavă, fiecare în casa lui."],[19,"Dar tu ești aruncat de pe mormântul tău ca o ramură urâcioasă, îmbrăcat cu cei uciși, care sunt străpunși de sabie, care se coboară în pietrele gropii; ca un cadavru călcat în picioare."],[20,"Nu te vei alătura lor la îngropare, pentru că ți-ai nimicit țara. Ți-ai ucis oamenii. Odraslele făcătorilor de rău nu vor fi numiți pentru totdeauna."],[21,"Pregătiți-vă pentru măcelăria copiilor săi din pricina nelegiuirii părinților lor, ca să nu se ridice și să stăpânească pământul și să umple suprafața lumii cu cetăți."],[22,"„Mă voi ridica împotriva lor”, zice Domnul armatelor, „și voi nimici din Babilon numele și rămășița și fiul și fiul fiului”, zice Domnul."],[23,"„Voi face din ea o stăpânire pentru porc-aș și pentru iazuri de apă. Îl voi mătura cu mătura distrugerii”, zice Domnul oștirilor."],[24,"Domnul oștirilor a jurat, zicând: „Cu siguranță, așa cum am gândit, așa se va întâmpla și așa cum am hotărât, așa va ține."],[25,"că voi zdrobi pe Asirian în țara mea și-l voi călca pe munții Mei. Atunci jugul Lui îi va părăsi, iar povara Lui va părăsi umerii lor."],[26,"Acesta este planul care este determinat pentru întregul pământ. Aceasta este mâna care este întinsă peste toate neamurile."],[27,"Căci Domnul oștirilor a plănuit și cine îl poate opri? Mâna lui este întinsă și cine o poate întoarce înapoi?”"],[28,"Această povară a fost în anul în care a murit regele Ahaz."],[29,"Nu vă bucurați, Filistie, toți, că s-a rupt toiagul care v-a lovit; căci din rădăcina șarpelui va ieși o viperă și rodul lui va fi un șarpe zburător de foc."],[30,"Întâiul născut al săracilor va mânca, iar cei nevoiași se vor culca în siguranță; și-ți voi ucide rădăcina cu foamete și rămășița ta va fi ucisă."],[31,"Urlă, poartă! Plange, oras! Sunteți topit, Filistie, toți; căci din miazănoapte iese fum și nu este rătăcitor în rândurile lui."],[32,"Ce vor răspunde ei solilor națiunii? Că Domnul a întemeiat Sionul și în ea se vor adăposti nenorociții poporului Său."]]],[15,[[1,"Povara Moabului."],[2,"S-au suit la Bayit și la Dibon, la înălțimi, să plângă. Moab se plânge de Nebo și de Medeba. Chelie este pe toate capetele lor. Fiecare barbă este tăiată."],[3,"Pe străzile lor, se îmbracă cu pânză de sac. Pe străzile lor și pe acoperișurile lor, toată lumea plânge, plângând din belșug."],[4,"Hesbon strigă împreună cu Eleale. Glasul lor se aude chiar și de Iahaz. De aceea oamenii înarmați din Moab strigă cu voce tare. Sufletele lor tremură în ei."],[5,"Inima mea strigă după Moab! Nobilii ei fug la Ţoar, la Eglat Şeleşiya; căci ei urcă pe urcușul Luhithului cu plâns; căci pe drumul spre Horonaim scot un strigăt de distrugere."],[6,"Căci apele Nimrimului vor fi pustii; căci iarba s-a ofilit, iarba fragedă cade, nu există nimic verde."],[7,"De aceea, ei vor duce din belșug din belșug pe care l-au dobândit și pe care l-au strâns peste pârâul sălciilor."],[8,"Căci strigătul a înconjurat hotarele Moabului, plânsul lui până la Eglaim și plânsul lui până la Beer Elim."],[9,"Căci apele lui Dimon sunt pline de sânge; căci voi aduce și mai mult asupra lui Dimon, un leu asupra celor scăpați din Moab și asupra rămășiței țării."]]],[16,[[1,"Trimite miei pentru stăpânitorul țării de la Sela în pustiu, la muntele fiicei Sionului."],[2,"Căci se va întâmpla ca niște păsări rătăcitoare, ca un cuib împrăștiat, așa vor fi fiicele lui Moab la vadurile Arnonului."],[3,"Dați un sfat! Faceți dreptate! Fă-ți umbra ca noaptea în mijlocul amiezii! Ascundeți proscrișii! Nu trăda fugarul!"],[4,"Lasă-i pe proscrișii mei să locuiască cu tine! Cât despre Moab, fii-i un loc de ascunziș de fața nimicitorului. Căci estorcatorul este adus la nimic. Distrugerea încetează. Asupritorii sunt mistuiți din pământ."],[5,"Un tron ​​va fi stabilit în bunătate iubitoare. Cineva va sta pe el în adevăr, în cortul lui David, judecând, căutând dreptate și iute să facă dreptate."],[6,"Am auzit de mândria lui Moab, că este foarte mândru; chiar și despre aroganța, mândria și mânia lui. Laudările lui nu sunt nimic."],[7,"De aceea Moab se va plânge pe Moab. Toată lumea va plânge. Vei plânge pentru prăjiturile cu stafide ale lui Kir Hareseth, total lovit."],[8,"Căci câmpiile Hesbonului lânceesc cu vița lui Sibma. Stăpânii neamurilor i-au rupt ramurile alese, care ajungeau până la Iazer, care rătăcea în pustie. Lăstarii lui au fost răspândiți în străinătate. Au trecut peste mare."],[9,"De aceea voi plânge cu plânsul lui Iazer pentru via lui Sibma. Te voi uda cu lacrimile mele, Heșbon și Eleale, căci peste roadele tale de vară și peste secerișul tău a căzut strigătul de luptă."],[10,"Bucuria este luată și bucuria din câmpul roditor; iar în vii nu va fi cântare, nici zgomot de bucurie. Nimeni nu va călca vin în teascuri. Am făcut să se oprească strigătele."],[11,"De aceea, inima mea sună ca o harpă pentru Moab, și lăuntricul meu pentru Chir Heres."],[12,"Se va întâmpla ca atunci când Moab se va prezenta, când se va obosi pe înălțime și va veni la sanctuarul său să se roage, să nu biruie."],[13,"Acesta este cuvântul pe care Domnul l-a spus despre Moab în vremurile trecute."],[14,"Dar acum DOMNUL a vorbit, zicând: „În trei ani, după cum îi va socoti un muncitor legat prin contract, slava Moabului va fi disprețuită, cu toată mulțimea lui mare; și rămășița va fi foarte mică și slabă.”"]]],[17,[[1,"Povara Damascului."],[2,"Orașele Aroer sunt părăsite. Ele vor fi pentru turme, care se vor culca și nimeni nu le va înspăimânta."],[3,"Cetatea va înceta din Efraim, și împărăția din Damasc și rămășița Siriei. Ei vor fi ca slava copiilor lui Israel”, zice Domnul armatelor."],[4,"„Se va întâmpla în ziua aceea când slava lui Iacov se va slăbi și grăsimea trupului său va deveni slabă."],[5,"Va fi ca atunci când secerătorul strânge grâul, iar brațul lui secera grânul. Da, va fi ca atunci când cineva culege grâne în valea Refaim."],[6,"Totuși, acolo vor rămâne culegări, ca scuturarea unui măslin, două sau trei măsline în vârful crengului de sus, patru sau cinci în ramurile cele mai îndepărtate ale unui pom roditor”, zice Domnul, Dumnezeul lui Israel."],[7,"În ziua aceea, oamenii se vor uita la Făcătorul lor, iar ochii lor vor avea respect pentru Sfântul lui Israel."],[8,"Nu se vor uita la altare, la lucrarea mâinilor lor; nici nu vor respecta ceea ce au făcut degetele lor, nici stâlpii din Așera, nici altarele pentru tămâie."],[9,"În ziua aceea, cetățile lor puternice vor fi ca locurile părăsite din pădure și de pe vârful munților, care au fost părăsite dinaintea copiilor lui Israel; și va fi o pustiire."],[10,"Căci ai uitat de Dumnezeul mântuirii tale și nu te-ai amintit de stânca puterii tale. De aceea plantezi plante plăcute și pui răsaduri străine."],[11,"În ziua sădirii tale, îl împotriviți. Dimineața, vă faceți sămânța să înflorească, dar recolta fuge în ziua durerii și a întristarii disperate."],[12,"Ah, zgomotul multor popoare care vuiesc ca vuietul mărilor; și năvălirea neamurilor care se năpustesc ca năvălirea apelor puternice!"],[13,"Neamurile se vor năvăli ca năvălirea multor ape, dar El le va mustra și vor fugi departe și vor fi urmărite ca pleava munților înaintea vântului și ca praful care se învârte înaintea furtunii."],[14,"Seara, iată, groază! Înainte de dimineață, nu mai sunt. Aceasta este partea celor care ne jefuiesc și soarta celor care ne jefuiesc."]]],[18,[[1,"Ah, țara foșnetului de aripi, care este dincolo de râurile Etiopiei;"],[2,"care trimite ambasadori pe malul mării, chiar și în vase de papirus pe ape, spunând: „Duceți-vă, solii iute, la o națiune înaltă și netedă, la un popor înfricoșător de la începuturi încoace, o națiune care măsoară și călcă în picioare, al cărei pământ îl împart râurile!”"],[3,"Voi toți locuitorii lumii și locuitorii pământului, când se înalță steagul pe munți, priviți! Când sună din trâmbiță, ascultă!"],[4,"Căci Domnul mi-a zis: „Voi liniști și voi vedea în locuința mea, ca o căldură limpede în lumina soarelui, ca un nor de rouă în căldura secerișului.”"],[5,"Căci înainte de seceriș, când floarea s-a terminat și floarea devine strugure care se coace, va tăia crenguțele cu cârlige și va tăia și va îndepărta ramurile răspândite."],[6,"Vor fi lăsați împreună pentru păsările răpitoare ale munților și pentru animalele pământului. Păsările răpitoare le vor mânca vara, iar toate animalele pământului le vor mânca iarna."],[7,"În vremea aceea, I se va aduce Domnului oștirilor un dar de la un popor înalt și neted, chiar de la un popor înfricoșător de la începutul lui încoace, o națiune care măsoară și călcă, a cărei pământ o împart râurile, până la locul numelui Domnului oștirilor, Muntele Sion."]]],[19,[[1,"Povara Egiptului."],[2,"Voi stârni pe egipteni împotriva egiptenilor și se vor lupta cu toți împotriva fratelui său și fiecare împotriva aproapelui său; oraș împotriva orașului și împărăție împotriva împărăției."],[3,"Spiritul egiptenilor va eșua în ei. le voi distruge sfatul. Ei vor căuta idolii, fermecătorii, cei care au spirite familiare și vrăjitorii."],[4,"Voi da pe egipteni în mâna unui domn crud. Un rege înverșunat va stăpâni peste ei, zice Domnul, Domnul oștirilor."],[5,"Apele mării se vor pierde, iar râul va fi irosit și se va usca."],[6,"Râurile vor deveni murdare. Fluxurile Egiptului vor fi diminuate și secate. Stuful și steagurile se vor ofili."],[7,"Pajiștile de lângă Nil, de pe malul Nilului și toate câmpurile semănate ale Nilului, vor deveni uscate, vor fi alungate și nu vor mai fi."],[8,"Pescarii se vor tângui și toți cei care pescuiesc în Nil se vor plânge, iar cei care întind mrejele pe ape vor lâncezi."],[9,"Mai mult, cei care lucrează în inul pieptănat și cei care țes pânză albă, vor fi derutați."],[10,"Stâlpii vor fi sparți în bucăți. Toți cei care lucrează pe bani vor fi întristați în suflet."],[11,"Prinții din Țoan sunt cu totul nebuni. Sfatul celor mai înțelepți sfetnici ai lui Faraon a devenit prost. Cum îi spui lui Faraon: „Eu sunt fiul înțelepților, fiul împăraților din vechime”?"],[12,"Atunci unde sunt înțelepții tăi? Lasă-i să-ți spună acum; şi să ştie ce a hotărât Domnul armatelor cu privire la Egipt."],[13,"Prinții din Țoan au devenit proști. Prinții din Memphis sunt înșelați. Ei au făcut să rătăcească Egiptul, cei care sunt piatra de temelie a triburilor ei."],[14,"Domnul a amestecat un duh de răutate în mijlocul ei; şi au făcut Egiptul să se rătăcească în toate lucrările lui, ca un om beat se clătina în vărsăturile sale."],[15,"Nici pentru Egipt nu va fi nici o lucrare pe care să o facă capul sau coada, ramura de palmier sau papurul."],[16,"În ziua aceea, egiptenii vor fi ca femeile. Se vor cutremura și se vor teme de strângerea mâinii Domnului oștirilor, pe care o strânge asupra lor."],[17,"Țara lui Iuda va deveni o groază pentru Egipt. Oricine se vorbește despre ea se va teme, din cauza planurilor Domnului oștirilor, pe care le hotărăște împotriva lui."],[18,"În ziua aceea, vor fi cinci cetăți în țara Egiptului care vorbesc limba Canaanului și vor jura Domnului oștirilor. Unul va fi numit „Orașul distrugerii”."],[19,"În ziua aceea, va fi un altar pentru Domnul în mijlocul țării Egiptului și un stâlp pentru Domnul la hotarul ei."],[20,"Va fi un semn și un martor pentru Domnul oștirilor în țara Egiptului; căci ei vor striga către DOMNUL din pricina asupritorilor și El le va trimite un mântuitor și un apărător și îi va izbăvi."],[21,"Domnul va fi cunoscut Egiptului și egiptenii îl vor cunoaște pe Domnul în ziua aceea. Da, ei se vor închina cu jertfe și jertfe și vor face un jurământ Domnului și îl vor împlini."],[22,"Domnul va lovi Egiptul, lovindu-i și vindecând. Se vor întoarce la DOMNUL și El va fi rugat de ei și îi va vindeca."],[23,"În ziua aceea, va fi o cale din Egipt către Asiria, şi asirianul va veni în Egipt, iar egiptenul în Asiria; iar egiptenii se vor închina împreună cu asirienii."],[24,"În ziua aceea, Israel va fi al treilea cu Egiptul și cu Asiria, o binecuvântare în pământ;"],[25,"pentru că Domnul armatelor i-a binecuvântat, zicând: „Binecuvântat să fie Egiptul poporul Meu, Asiria lucrarea mâinilor Mele și Israel moștenirea mea!”"]]],[20,[[1,"În anul în care Tartan a venit la Asdod, când l-a trimis Sargon, împăratul Asiriei, și a luptat împotriva Asdodului și l-a luat;"],[2,"în vremea aceea, Domnul a vorbit prin Isaia, fiul lui Amoţ, zicând: „Du-te, desprinde-ţi sacul de pe brâu şi ia-ţi încălţămintea de pe picioarele tale.” A făcut asta, mergând gol și desculț."],[3,"Domnul a spus: „După cum robul Meu Isaia a umblat gol și desculț trei ani, ca semn și minune pentru Egipt și pentru Etiopia,"],[4,"deci regele Asiriei îi va duce pe robii Egiptului și pe cei exilați din Etiopia, tineri și bătrâni, goi și desculți și cu fesele descoperite, spre rușinea Egiptului."],[5,"Ei vor fi înspăimântați și încurcați, din cauza Etiopiei așteptării lor și a Egiptului slava lor."],[6,"Locuitorii acestei țări de coastă vor spune în ziua aceea: „Iată, aceasta este așteptarea noastră, unde am fugit pentru ajutor pentru a fi eliberați de regele Asiriei. Și noi, cum vom scăpa?’”"]]],[21,[[1,"Povara pustiei marii."],[2,"Mi se declară o viziune îngrozitoare. Omul trădător se comportă cu perfid, iar distrugătorul distruge. Urcă-te, Elam; atac! Am oprit toate suspinele Media."],[3,"De aceea coapsele mele sunt pline de suferință. Durerile m-au cuprins, ca durerile unei femei în travaliu. Mă doare atât de mult încât nu pot auzi. Sunt atât de consternat încât nu pot să văd."],[4,"Inima îmi bate. Groaza m-a speriat. Amurgul pe care mi l-am dorit s-a transformat în tremurător pentru mine."],[5,"Ei pregătesc masa. Au pus ceasul. Ei mănâncă. Ei beau. Ridicați-vă, prinți, ungeți scutul!"],[6,"Căci Domnul mi-a zis: „Du-te, pune un paznic, să spună ce vede."],[7,"Când vede o trupă, călăreți în perechi, o trupă de măgari, o trupă de cămile, va asculta cu sârguință, cu mare atenție.”"],[8,"A strigat ca un leu: „Doamne, stau mereu pe turnul de veghe în timpul zilei și în fiecare noapte stau la postul meu."],[9,"Iată, vine o trupă de oameni, călăreți în perechi.” El a răspuns: „A căzut, a căzut Babilonul; și toate imaginile gravate ale zeilor ei sunt zdrobite la pământ."],[10,"Tu ești treieratul meu și grăunta podelei mele!” Ceea ce am auzit de la Domnul oștirilor, Dumnezeul lui Israel, v-am spus."],[11,"Povara lui Dumah."],[12,"Paznicul a spus: \"Vine dimineața și de asemenea noaptea. Dacă vrei să întrebi, întreabă. Întoarce-te iar.\""],[13,"Povara asupra Arabiei."],[14,"I-au adus apă celui care era sete. Locuitorii din țara Tema i-au întâlnit pe fugari cu pâinea lor."],[15,"Căci au fugit de săbii, de sabia scoasă, de arcul îndoit și de arșița luptei."],[16,"Căci Domnul mi-a zis: „În decurs de un an, după cum o va socoti un muncitor legat de contract, toată slava lui Chedar se va pierde,"],[17,"iar restul numărului arcașilor, a bărbaților puternici ai fiilor lui Chedar, va fi puțin; căci Domnul, Dumnezeul lui Israel, a spus-o.”"]]],[22,[[1,"Povara văii vederii."],[2,"Ceea ce ești plin de strigăte, cetate zbuciumată, cetate veselă, ucișii tăi nu sunt uciși de sabie și nici nu mor în luptă."],[3,"Toți conducătorii tăi au fugit împreună. Au fost legați de arcași. Toți cei care au fost găsiți de tine au fost legați împreună. Au fugit departe."],[4,"De aceea am zis: „Depărtează-te de mine, voi plânge amar, nu te chinui să mă mângâie pentru nimicirea fiicei poporului meu."],[5,"Căci este o zi de confuzie, de călcare în picioare și de nedumerire din partea Domnului, Domnul oștirilor, în valea vedeniei, a prăbușirii zidurilor și a strigătei către munți.”"],[6,"Elam și-a purtat tolba, cu care de oameni și călăreți; iar Kir a descoperit scutul."],[7,"Cele mai alese văi ale tale erau pline de care, iar călăreții s-au așezat la poartă."],[8,"El a luat acoperământul lui Iuda; și te-ai uitat în ziua aceea la armura din casa pădurii."],[9,"Ai văzut că spărturile cetăţii lui David erau multe; și ai adunat apele iazului de jos."],[10,"Ai numărat casele Ierusalimului și ai dărâmat casele pentru a întări zidul."],[11,"Ai făcut și un rezervor între cei doi pereți pentru apa bătrânului ștrand. Dar nu te-ai uitat la cel care a făcut asta și nici nu ai avut respect pentru cel care a plănuit-o cu mult timp în urmă."],[12,"În ziua aceea, Domnul, Domnul oştirilor, a chemat la plâns, la bocete, la chelie şi la îmbrăcat în sac;"],[13,"și iată, este bucurie și veselie, uciderea vitelor și uciderea oilor, mâncarea din carne și băutura vinului: „Să mâncăm și să bem, căci mâine vom muri”."],[14,"Domnul oștirilor s-a descoperit la urechile mele: „Cu siguranță această nelegiuire nu vă va fi iertată până când veți muri”, zice Domnul, Domnul oștirilor."],[15,"Domnul, Domnul oștirilor zice: „Du-te, du-te la acest vistier, la Șebna, care este peste casa, și spune:"],[16,"'Ce faci aici? Cine te are aici, că ai săpat aici un mormânt?’ S-a tăiat un mormânt în înălțime, și-a dăltuit o locuință în stâncă!”"],[17,"Iată, Domnul te va birui și te va arunca cu violență. Da, el te va prinde ferm."],[18,"El te va arunca cu siguranță în jurul și în jurul tău și te va arunca ca o minge într-o țară mare. Acolo vei muri și acolo vor fi carele slavei tale, ocară a casei stăpânului tău."],[19,"Te voi da afară din birou. Vei fi tras în jos de la stația ta."],[20,"Se va întâmpla în ziua aceea că voi chema pe robul meu Eliachim, fiul lui Hilchia,"],[21,"și-l voi îmbrăca cu haina ta și-l voi întări cu brâul tău. Îți voi încredința guvernul în mâna lui; şi el va fi un tată pentru locuitorii Ierusalimului şi pentru casa lui Iuda."],[22,"Voi pune cheia casei lui David pe umărul lui. El va deschide și nimeni nu va închide. El va închide și nimeni nu va deschide."],[23,"Îl voi prinde ca un cui într-un loc sigur. El va fi un tron ​​de glorie pentru casa tatălui său."],[24,"Ei vor atârna de el toată slava casei tatălui său, urmașii și neamul, orice vas mic, de la cupe până la toate ulcioarele."],[25,"„În ziua aceea, zice Domnul oștirilor, cuiul care a fost prins într-un loc sigur va ceda, va fi tăiat și va cădea. Povara care era pe el va fi tăiată, căci Domnul a spus-o.”"]]],[23,[[1,"Povara Tirului."],[2,"Stați liniștiți, locuitori ai coastei, pe care negustorii Sidonului, care trec peste mare, i-au umplut."],[3,"Pe ape mari, sămânța Sihorului, recolta Nilului, era venitul ei. Ea era piața națiunilor."],[4,"Rușine-ți, Sidon; căci marea, fortăreaţa mării, a vorbit, zicând: „N-am avut naştere, n-am născut, n-am hrănit tineri şi n-am crescut fecioare”."],[5,"Când va veni vestea în Egipt, ei vor fi îndurerați de vestea Tirului."],[6,"Treci la Tarsis! Vaiati, voi locuitori ai coastei!"],[7,"Este aceasta cetatea ta veselă, a cărei vechime este de vremuri străvechi, ale cărei picioare au dus-o departe pentru a călători?"],[8,"Cine a plănuit asta împotriva Tirului, dătătorul de coroane, ai cărui negustori sunt prinți, ai cărui negustori sunt cinstiții pământului?"],[9,"Domnul oștirilor a plănuit-o, pentru a păta mândria oricărei slave, pentru a aduce în dispreț pe toți cei cinstiți de pe pământ."],[10,"Treci prin țara ta ca Nilul, fiica lui Tarsis. Nu mai există nicio reținere."],[11,"Și-a întins mâna peste mare. El a zguduit împărățiile. Domnul a poruncit distrugerea cetăților lui Canaan."],[12,"El a spus: \"Nu te vei mai bucura, fecioară asuprită, fiica Sidonului. Scoală-te, treci la Chitim; nici acolo nu vei avea odihnă.\""],[13,"Iată, țara caldeenilor. Acest popor nu a existat. Asirienii au întemeiat-o pentru cei care locuiesc în pustie. Și-au instalat turnurile. I-au răsturnat palatele. Au făcut-o o ruină."],[14,"Urlați, corăbii din Tarsis, căci cetatea voastră este pustiită!"],[15,"Se va întâmpla în ziua aceea că Tirul va fi uitat șaptezeci de ani, după zilele unui singur rege. După sfârșitul a șaptezeci de ani, Tirului va fi ca în cântecul desfrânatei."],[16,"Luați o harpă; du-te prin oraș, prostituată care ai fost uitată. Faceți o melodie dulce. Cântați multe cântece, ca să vă amintiți."],[17,"După sfârșitul a șaptezeci de ani, Domnul va vizita Tirul. Ea se va întoarce la salariul ei și se va desfrâna cu toate împărățiile lumii de pe suprafața pământului."],[18,"Marfa ei și plata ei vor fi sfințenie pentru Domnul. Nu va fi prețuit și nici păstrat; pentru că marfa ei va fi pentru cei ce locuiesc înaintea Domnului, să mănânce din belșug și pentru îmbrăcăminte trainică."]]],[24,[[1,"Iată, DOMNUL golește pământul, îl pustiește, îl întoarce cu susul în jos și își împrăștie locuitorii."],[2,"Va fi ca și cu poporul, așa și cu preotul; ca si cu slujitorul, asa si cu stapanul sau; ca si cu slujnica, asa si cu stapana; ca și cu cumpărătorul, așa și cu vânzătorul; ca si cu creditorul, asa si cu debitorul; ca și cu cel care primește dobândă, așa și cu cel care dă dobândă."],[3,"Pământul va fi complet golit și pustiu cu totul; căci Domnul a rostit acest cuvânt."],[4,"Pământul plânge și se stinge. Lumea lâncește și dispare. Oamenii înalți ai pământului lâncezesc."],[5,"De asemenea, pământul este spurcat sub locuitorii săi, pentru că ei au călcat legile, au încălcat legile și au încălcat legământul veșnic."],[6,"De aceea blestemul a mistuit pământul și cei ce locuiesc pe el sunt găsiți vinovați. De aceea locuitorii pământului sunt arse și puțini oameni au rămas."],[7,"Vinul nou plânge. Vița lâncezește. Tot oftat vesel."],[8,"Veselia tamburinelor încetează. Sunetul celor ce se bucură se termină. Bucuria harpei încetează."],[9,"Nu vor bea vin cu un cântec. Băutura tari va fi amară pentru cei care o beau."],[10,"Orașul confuz este dărâmat. Fiecare casă este închisă, ca să nu intre nimeni."],[11,"Se aude plâns pe străzi din cauza vinului. Toată bucuria este întunecată. Veselia pământului a dispărut."],[12,"Cetatea este lăsată în pustiire, iar poarta este lovită de distrugere."],[13,"Căci așa va fi în pământ între popoare, ca scuturarea unui măslin, ca culegere la sfârșitul recoltei."],[14,"Aceștia își vor ridica glasul. Ei vor striga după măreția Domnului. Ei plâng cu voce tare dinspre mare."],[15,"De aceea, proslăviți pe Domnul în răsărit, chiar numele Domnului, Dumnezeul lui Israel, în insulele mării!"],[16,"Din marginea pământului am auzit cântece. Slavă celor drepți!"],[17,"Frica, groapa și cursa sunt asupra voastră, care locuiți pe pământ."],[18,"Se va întâmpla ca cel ce fuge de zgomotul fricii să cadă în groapă; iar cel ce se suie din mijlocul gropii va fi prins în cursă; căci ferestrele de sus se deschid şi temeliile pământului tremură."],[19,"Pământul este complet rupt. Pământul este sfâșiat. Pământul este zguduit violent."],[20,"Pământul se va clătina ca un om beat și se va legăna înainte și înapoi ca un hamac. Neascultarea lui va fi grea asupra ei și va cădea și nu se va ridica din nou."],[21,"Se va întâmpla în ziua aceea că Domnul va pedepsi oastea celor înalți de sus și pe împărații pământului pe pământ."],[22,"Ei vor fi adunați împreună, precum prizonierii sunt adunați în groapă și vor fi închiși în închisoare; iar după multe zile vor fi vizitaţi."],[23,"Atunci luna va fi încurcată și soarele va fi rușinat; căci Domnul oştirilor va domni pe muntele Sionului şi în Ierusalim; și slava va fi înaintea bătrânilor lui."]]],[25,[[1,"Doamne, Tu ești Dumnezeul meu. te voi înălța! Îți voi lăuda numele, căci ai făcut lucruri minunate, lucruri plănuite de mult, în deplină credincioșie și adevăr."],[2,"Căci ai făcut o cetate într-o grămadă, o cetate întărită într-o ruină, un palat al străinilor să nu fie cetate. Nu va fi construit niciodată."],[3,"De aceea un popor puternic te va slăvi. Un oraș cu națiuni minunate se va teme de tine."],[4,"Căci tu ai fost o fortăreață pentru sărac, o fortăreață pentru sărac în necazul lui, o adăpost împotriva furtunii, o umbră împotriva căldurii, când suflarea celor de temut este ca o furtună împotriva zidului."],[5,"Ca căldura într-un loc uscat vei doborî zgomotul străinilor; precum căldura de la umbra unui nor, cântecul celor de temut va fi scăzut."],[6,"Pe acest munte, Domnul armatelor va face din toate popoarele o sărbătoare a cărnii alese, o sărbătoare a vinurilor alese, a cărnii alese pline de măduvă, a vinurilor alese bine rafinate."],[7,"El va nimici pe acest munte suprafața învelișului care acoperă toate popoarele și vălul care este întins peste toate neamurile."],[8,"El a înghițit moartea pentru totdeauna! Domnul, Domnul, va șterge lacrimile de pe toate fețele. El va lua ocara poporului Său de pe tot pământul, căci Domnul a spus-o."],[9,"În ziua aceea se va spune: „Iată, acesta este Dumnezeul nostru! Noi l-am așteptat și El ne va mântui! Acesta este Domnul! L-am așteptat. Ne vom bucura și ne vom bucura de mântuirea Lui!”"],[10,"Căci mâna Domnului se va odihni pe muntele acesta."],[11,"Își va întinde mâinile în mijlocul ei, precum cel care înoată își întinde mâinile pentru a înota, dar mândria lui va fi smerită împreună cu meșteșugul mâinilor lui."],[12,"El a dărâmat cetatea înaltă a zidurilor voastre, a pus jos și a dus la pământ până în țărână."]]],[26,[[1,"În ziua aceea, se va cânta acest cântec în țara lui Iuda:"],[2,"Deschideți porțile, ca să intre neamul drept:"],[3,"Vei păstra mintea oricui este neclintită într-o pace desăvârșită,"],[4,"Încrede-te în Domnul pentru totdeauna;"],[5,"Căci El a doborât pe cei ce locuiesc în înălțime, cetatea înaltă."],[6,"Piciorul îl va călca,"],[7,"Calea celui drept este dreptatea."],[8,"Da, în calea judecăților Tale, Doamne, te-am așteptat."],[9,"Cu sufletul meu te-am dorit noaptea."],[10,"Să li se arate favoare celor răi,"],[11,"Doamne, mâna Ta este ridicată, dar ei nu văd;"],[12,"Doamne, ne vei rândui pacea,"],[13,"Doamne, Dumnezeul nostru, alți domni în afară de Tine au stăpânit peste noi,"],[14,"Morții nu vor trăi."],[15,"Tu ai înmulțit neamul, Doamne."],[16,"Doamne, în necazuri te-au vizitat."],[17,"La fel ca o femeie care are un copil, care se apropie de ora nașterii,"],[18,"Am fost cu un copil."],[19,"Morții tăi vor trăi."],[20,"Vino, poporul meu, intră în camerele tale,"],[21,"Căci, iată, Domnul iese din locul său ca să pedepsească pe locuitorii pământului pentru nelegiuirea lor."]]],[27,[[1,"În ziua aceea, Domnul va pedepsi cu sabia Sa tare, mare și puternică pe Leviatan, șarpele care fugă, și Leviatan, șarpele răsucit; și va ucide balaurul care este în mare."],[2,"În ziua aceea, cântă-i: „O vie plăcută!"],[3,"Eu, Domnul, sunt păzitorul ei. O voi uda în fiecare clipă. Ca să nu-l strice cineva, îl voi păstra zi și noapte."],[4,"Mânia nu este în mine, dar dacă aș găsi mărăcini și spini, aș lupta! Aș mărșălui asupra lor și le-aș arde împreună."],[5,"Sau să-mi apuce puterea, ca să facă pace cu mine. Lasă-l să facă pace cu mine.”"],[6,"În zilele viitoare, Iacov va prinde rădăcini. Israelul va înflori și va înmuguri. Vor umple suprafața lumii cu fructe."],[7,"I-a lovit el așa cum i-a lovit pe cei care i-au lovit? Sau sunt uciși așa cum au fost uciși cei care i-au ucis?"],[8,"În măsură, când îi trimiți, te lupți cu ei. El i-a îndepărtat cu suflarea lui aspră în ziua vântului de răsărit."],[9,"Prin aceasta nelegiuirea lui Iacov va fi iertată și acesta este tot rodul ridicării păcatului său: că el face toate pietrele altarului ca niște pietre de cretă, care sunt bătute în bucăți, astfel încât stâlpii din Așera și altarele de tămâie să nu se mai ridice."],[10,"Căci cetatea întărită este singură, o locuință pustie și părăsită, ca pustia. Acolo se va hrăni vițelul și acolo se va culca și îi va mistui ramurile."],[11,"Când ramurile sale sunt ofilite, acestea vor fi rupte. Femeile vor veni și le vor da foc, căci sunt un popor neînțelegător. De aceea, cel care le-a făcut nu va avea milă de ei, iar cel care le-a format nu le va arăta nicio favoare."],[12,"Se va întâmpla în ziua aceea că DOMNUL va bate din râul care curge Eufratul până la pârâul Egiptului; și veți fi adunați unul câte unul, copiii lui Israel."],[13,"Se va întâmpla în ziua aceea că se va suna o trâmbiță mare; și vor veni cei care erau gata să piară în țara Asiriei și cei care au fost alungați în țara Egiptului; și se vor închina Domnului pe muntele sfânt din Ierusalim."]]],[28,[[1,"Vai de cununa mândriei a bețivilor lui Efraim și de floarea stinsă a frumuseții sale glorioase, care se află pe capul văii roditoare a celor biruiți de vin!"],[2,"Iată, Domnul are unul care este puternic și puternic. Ca o furtună de grindină, o furtună nimicitoare și ca o furtună de ape puternice care se revarsă, îi va arunca cu mâna lui pe pământ."],[3,"Cununa mândriei bețivilor lui Efraim va fi călcată în picioare."],[4,"Floarea stinsă a frumuseții sale glorioase, care se află pe capul văii roditoare, va fi ca primul smochin copt înainte de vară, pe care cineva îl culege și îl mănâncă de îndată ce îl vede."],[5,"În ziua aceea, Domnul oștirilor va deveni o cunună de slavă și o diademă de frumusețe pentru restul poporului Său,"],[6,"și un duh de dreptate pentru cel ce stă la judecată și putere pentru cei care întorc bătălia de la poartă."],[7,"De asemenea, se tăvălesc cu vin și se clătinesc cu băutura tare. Preotul și profetul se tăvălesc cu băutură tare. Sunt înghițiți de vin. Se clătinesc cu băutura tare. Ei greșesc în viziune. Ei se poticnesc la judecată."],[8,"Căci toate mesele sunt complet pline de vărsături murdare și murdărie."],[9,"Pe cine va învăța el cunoașterea? Cui îi va explica el mesajul? Cei care sunt înțărcați din lapte și scoși din sâni?"],[10,"Căci este poruncă peste poruncă, poruncă peste poruncă; linie pe linie, linie pe linie; aici puțin, acolo puțin."],[11,"Dar el va vorbi acestui neam cu buze bâlbâite și într-o altă limbă,"],[12,"Căruia i-a zis: „Acesta este locul de odihnă. Odihnește-i celui obosit” și „Acesta este înviorarea”. totuși nu au vrut să audă."],[13,"De aceea, cuvântul Domnului va fi pentru ei poruncă după poruncă, poruncă după poruncă; linie pe linie, linie pe linie; aici puțin, acolo puțin; ca să meargă, să cadă cu spatele, să fie zdrobiți, să fie prinși în capcană și să fie prinși."],[14,"De aceea, ascultați cuvântul Domnului, batjocoritorilor, care stăpâniți pe acest popor în Ierusalim:"],[15,"„Pentru că ai spus: „Noi am făcut un legământ cu moartea și suntem de acord cu mormântul. Când va trece biciul care se revarsă, nu va veni la noi, căci ne-am făcut minciunile refugiu și ne-am ascuns sub minciună.”"],[16,"De aceea, Domnul, Domnul, zice: „Iată, pun în Sion ca temelie o piatră, o piatră încercată, o piatră prețioasă a temeliei sigure. Cine crede să nu se grăbească."],[17,"Voi face dreptatea firul de măsurare și dreptatea firul de plumb. Grindina va mătura adăpostul minciunii, iar apele vor revărsa ascunzătoarea."],[18,"Legământul tău cu moartea va fi anulat și înțelegerea ta cu mormântul nu va rămâne în picioare. Când flagelul debordant va trece, atunci vei fi călcat în picioare de el."],[19,"De câte ori trece prin el, te va prinde; căci dimineața de dimineață va trece, ziua și noaptea; și nu va fi altceva decât groază să înțelegi mesajul.”"],[20,"Căci patul este prea scurt pentru a se întinde, iar pătura este prea îngustă pentru a te înfășura."],[21,"Căci Domnul se va ridica ca pe muntele Perazim. Se va mânia ca în valea Gabaonului; ca el să-și facă treaba, munca lui neobișnuită, și să-și realizeze actul său, actul său extraordinar."],[22,"Acum, deci, nu fiți batjocori, ca nu cumva legăturile voastre să se întărească; căci am auzit o poruncă de nimicire de la Domnul, Domnul oştirilor, pe tot pământul."],[23,"Ascultă și auzi vocea mea! Ascultă și auzi discursul meu!"],[24,"Cel ce ară să semene ara încontinuu? Continuă să întoarcă pământul și să spargă boțurile?"],[25,"Când i-a nivelat suprafața, nu plantează el mărar și împrăștie sămânța de chimen și nu pune grâul pe rânduri, orzul la locul rânduit și spelta la locul lui?"],[26,"Căci Dumnezeul lui îl învață în judecată dreaptă și îl învață."],[27,"Căci nu se treiera mărarul cu un instrument ascuțit, nici roata căruței nu se învârte peste chimen; dar mararul se bate cu un bat, iar chimenul cu un toiag."],[28,"Faina de paine trebuie macinata; deci nu o va treiera mereu. Deși conduce roata căruciorului său de treierat peste el, caii lui nu o macină."],[29,"Aceasta iese și de la Domnul oștirilor, care este minunat în sfaturi și excelent în înțelepciune."]]],[29,[[1,"Vai de Ariel! Ariel, orașul în care a tăbărât David! Adaugă de la an la an; să vină sărbătorile;"],[2,"atunci o voi tulbura pe Ariel, și acolo va fi jale și bocete. Ea va fi pentru mine ca o vatră de altar."],[3,"Voi tăbăra împotriva ta de jur împrejurul tău și te voi asedi cu trupe așezate. Voi ridica lucrări de asediu împotriva ta."],[4,"Vei fi doborât și vei vorbi din pământ. Discursul tău va bolborosi din praf. Glasul tău va fi ca al celui care are un spirit familiar, din pământ, iar vorbirea ta va șopti din țărână."],[5,"Dar mulțimea vrăjmașilor tăi va fi ca țărâna fină, și mulțimea celor nemiloși ca pleava care suflă. Da, va fi într-o clipă, brusc."],[6,"Ea va fi vizitată de Domnul oștirilor cu tunete, cu cutremur, cu zgomot mare, cu vârtej și furtună și cu flacăra unui foc mistuitor."],[7,"Mulțimea tuturor neamurilor care luptă împotriva Arielei, chiar și toți cei care luptă împotriva ei și a fortății ei și care o frământă, va fi ca un vis, o vedenie a nopții."],[8,"Va fi ca atunci când un om flămând visează și iată că mănâncă; dar el se trezește și foamea nu este satisfăcută; sau ca atunci când un om însetat visează și iată că bea; dar el se trezește și iată că este leșinat și îi este încă sete. Mulțimea tuturor națiunilor care luptă împotriva muntelui Sion va fi așa."],[9,"Pauza si mirare! Orbiți-vă și fiți orbi! Sunt beți, dar nu cu vin; se clătină, dar nu cu băutura tari."],[10,"Căci Domnul a vărsat peste voi un duh de somn adânc și v-a închis ochii, proorocilor; și v-a acoperit capetele, văzătorilor."],[11,"Toată viziunea a devenit pentru tine ca cuvintele unei cărți pecetluite, pe care oamenii o dau unui om educat, spunând: „Citește aceasta, te rog!” iar el spune: „Nu pot, pentru că este pecetluită”;"],[12,"iar cartea este predată unuia care nu este educat, spunând: „Citește asta, te rog”; și el spune: „Nu știu să citesc”."],[13,"Domnul a spus: „Pentru că poporul acesta se apropie cu gura și Mă cinstește cu buzele, dar și-a îndepărtat inima departe de Mine și frica lor de Mine este o poruncă a oamenilor care a fost învățată;"],[14,"de aceea, iată, voi începe să fac o lucrare minunată în mijlocul acestui popor, chiar o lucrare minunată și o minune; și înțelepciunea înțelepților lor va pieri, și priceperea înțelepților lor va fi ascunsă”."],[15,"Vai de cei care își ascund adânc sfatul de la Domnul și ale căror fapte sunt în întuneric și care spun: „Cine ne vede?” și „Cine ne cunoaște?”"],[16,"Dai lucrurile peste cap! Dacă olarul ar fi considerat ca lutul, ca lucrul făcut să spună despre cel care l-a făcut: „El nu m-a făcut pe mine”; sau lucrul format spune despre cel care l-a alcătuit: „Nu are pricepere”?"],[17,"Nu este încă foarte puțin și Libanul va fi prefăcut într-un câmp roditor, iar câmpul roditor va fi privit ca o pădure?"],[18,"În ziua aceea, surzii vor auzi cuvintele cărții, iar ochii orbilor vor vedea din întuneric și din întuneric."],[19,"Și cei smeriți își vor spori bucuria în Domnul și cei săraci dintre oameni se vor bucura de Sfântul lui Israel."],[20,"Căci cel nemilos este nimicit, și batjocorul încetează și toți cei care sunt vigilenți să facă rău sunt nimiciți,"],[21,"care fac o persoană să fie acuzată printr-un cuvânt și întinsă o cursă celui care mustră în poartă și care lipsesc pe cel nevinovat de dreptate cu mărturie mincinoasă."],[22,"De aceea, Domnul, care l-a răscumpărat pe Avraam, spune despre casa lui Iacov: „Iacov nu se va mai rușina și nu-i va păli fața."],[23,"Dar când va vedea copiii lui, lucrarea mâinilor Mele, în mijlocul lui, ei vor sfinți numele Meu. Da, ei îl vor sfinți pe Sfântul lui Iacov și se vor încânta de Dumnezeul lui Israel."],[24,"Și cei ce greșesc în duh vor ajunge la înțelegere, iar cei care se crâcnesc vor primi învățătură.”"]]],[30,[[1,"„Vai de copiii răzvrătiți”, zice Domnul, „care se sfătuiesc, dar nu de la Mine și care se unesc, dar nu cu Duhul Meu, ca să adauge păcatul la păcat;"],[2,"care au pornit să coboare în Egipt fără să-mi ceară sfatul, să se întărească în puterea lui Faraon și să se adăpostească la umbra Egiptului!"],[3,"De aceea puterea lui Faraon va fi rușinea ta și scăparea în umbra Egiptului va fi deznădejdea ta."],[4,"Căci prinții lor sunt la Țoan, iar ambasadorii lor au venit la Hanes."],[5,"Toți vor fi rușinați de un popor care nu-i poate folosi, care nu este un ajutor, nici un folos, ci o rușine și, de asemenea, o ocără.”"],[6,"Povara animalelor din Sud."],[7,"Căci Egiptul ajută în zadar și fără rost; de aceea i-am numit-o Rahab, care stă nemișcată."],[8,"Acum mergeți, scrieți-o înaintea lor pe o tablă și înscrieți-o într-o carte, ca să fie pentru vremea care va veni în vecii vecilor."],[9,"Căci este un popor răzvrătit, copii mincinoși, copii care nu vor asculta legea Domnului;"],[10,"care le spun văzătorilor: „Nu vezi!” iar profeţii: „Nu ne prorociţi lucruri drepte, spuneţi-ne lucruri plăcute, profeţiţi înşelăciuni."],[11,"Iesi din drum. Întoarce-te de la potecă. Fă-l pe Sfântul lui Israel să înceteze dinaintea noastră.”"],[12,"De aceea Sfântul lui Israel zice: „Pentru că disprețuiești acest cuvânt și te încrezi în asuprire și răutate și te bizui pe el,"],[13,"de aceea această nelegiuire va fi pentru voi ca o breșă gata să cadă, care se umflă într-un zid înalt, a cărei spargere vine deodată într-o clipă."],[14,"El o va sparge precum se sparge un vas de olar, făcându-l în bucăți fără cruțare, ca să nu se găsească printre bucățile rupte o bucată suficient de bună pentru a lua focul din vatră sau pentru a scoate apă din cisternă.”"],[15,"Căci așa a zis Domnul, Domnul, Sfântul lui Israel: „Veți fi mântuiți în întoarcere și odihnă, puterea voastră va fi în liniște și în încredere.” ai refuzat,"],[16,"dar tu ai spus: „Nu, căci vom fugi pe cai”. de aceea vei fugi; și: „Vom călare pe iute”; de aceea cei care te urmăresc vor fi iute."],[17,"O mie vor fugi la amenințarea unuia. La amenințarea cu cinci, vei fugi până vei rămâne ca un far pe vârful unui munte și ca un stindard pe un deal."],[18,"De aceea, Domnul va aștepta, ca să aibă milă de tine; și de aceea va fi înălțat, ca să aibă milă de tine, căci Domnul este un Dumnezeu al dreptății. Fericiți toți cei care îl așteaptă."],[19,"Căci poporul va locui în Sion, la Ierusalim. Nu vei mai plânge. El va avea cu siguranță milă cu tine la glasul strigătului tău. Când te va auzi, îți va răspunde."],[20,"Deși Domnul îți va da pâinea necazului și apa necazului, totuși învățătorii tăi nu vor mai fi ascunși, ci ochii tăi vor vedea pe învățătorii tăi;"],[21,"și când te vei întoarce la dreapta și când te vei întoarce la stânga, urechile tale vor auzi un glas în spatele tău, care va spune: „Aceasta este calea. Umblă pe ea”."],[22,"Vei pângări acoperirea imaginilor tale gravate cu argint și placarea imaginilor tale topite cu aur. Le vei arunca ca pe un lucru necurat. Îi vei spune: „Du-te!”"],[23,"El va da ploaia pentru sămânța ta, cu care vei semăna pământul; iar pâinea din înmulțirea pământului va fi bogată și din belșug. În ziua aceea, vitele voastre se vor hrăni în pășuni mari."],[24,"De asemenea, boii și măgarii care lucrează pământul vor mânca furaje gustoase, care a fost vârâtă cu lopata și cu furculița."],[25,"Pe fiecare munte înalt și pe fiecare deal înalt, în ziua măcelului mare, când vor cădea turnurile, vor fi pâraie și pâraie de apă."],[26,"Mai mult, lumina lunii va fi ca lumina soarelui și lumina soarelui va fi de șapte ori mai strălucitoare, ca lumina de șapte zile, în ziua în care Domnul va lega rănirea poporului Său și va vindeca rana de care au fost loviti."],[27,"Iată, numele Domnului vine de departe, arzând de mânia lui și în fum dens care se ridică. Buzele lui sunt pline de indignare. Limba lui este ca un foc mistuitor."],[28,"Suflarea lui este ca un pârâu care se revarsă, care ajunge până la gât, pentru a cerne neamurile cu sita distrugerii. Un căpăstru care duce la ruină va fi în fălcile popoarelor."],[29,"Vei avea un cântec, ca în noaptea când se oficiază o sărbătoare sfântă, și veselia inimii, ca atunci când cineva merge cu flaut pentru a veni la muntele Domnului, la Stânca lui Israel."],[30,"Domnul va face să se audă glasul Lui glorios și va arăta coborârea brațului Lui, cu mânia mâniei Lui și cu flacăra unui foc mistuitor, cu explozie, furtună și grindină."],[31,"Căci prin glasul Domnului asirianul va fi înspăimântat. Îl va lovi cu toiagul."],[32,"Fiecare lovitură din toiagul pedepsei, pe care Domnul o va pune peste el, va fi cu sunet de tamburine și de harpe. El va lupta cu ei în bătălii, brandind arme."],[33,"Căci locul lui de ardere a fost de mult gata. Da, este pregătit pentru rege. El și-a făcut rugul adânc și mare cu foc și mult lemn. Suflarea Domnului, ca un râu de sulf, o aprinde."]]],[31,[[1,"Vai de cei care coboară în Egipt după ajutor,"],[2,"Dar și el este înțelept și va aduce nenorocire,"],[3,"Acum egiptenii sunt oameni, nu Dumnezeu;"],[4,"Căci Domnul îmi spune:"],[5,"Precum păsările plutesc, așa Domnul armatelor va proteja Ierusalimul."],[6,"Întoarceți-vă la cel de care v-ați răzvrătit profund, copiii lui Israel."],[7,"Căci în ziua aceea fiecare își va arunca idolii de argint și idolii de aur, păcatul pe care mâinile tale le-au făcut pentru tine."],[8,"„Asirianul va cădea de sabie, nu de om;"],[9,"Stânca lui va trece din pricina groază,"]]],[32,[[1,"Iată, un rege va domni cu dreptate,"],[2,"Omul va fi ca o ascunzătoare de vânt,"],[3,"Ochii celor ce văd nu vor fi întunecați,"],[4,"Inima erupției va înțelege cunoașterea,"],[5,"Prostul nu va mai fi numit nobil,"],[6,"Căci nebunul va spune nebunie,"],[7,"Căile ticălosului sunt rele."],[8,"Dar nobilul creează lucruri nobile,"],[9,"Ridicați-vă, femeile care sunteți în largul lor! Ascultă-mi vocea!"],[10,"Zile de peste un an veți fi tulburate, femei nepăsătoare;"],[11,"Tremurați, femeilor care vă simțiți în largul lor!"],[12,"Bate-ți sânii pentru câmpurile plăcute,"],[13,"Spini și mărăcini se vor ridica pe pământul poporului meu;"],[14,"Căci palatul va fi părăsit."],[15,"până când Duhul va fi turnat de sus peste noi,"],[16,"Atunci dreptatea va locui în pustie;"],[17,"Lucrarea dreptății va fi pacea,"],[18,"Poporul meu va locui într-o locuință liniștită,"],[19,"deși grindina aplatizează pădurea,"],[20,"Binecuvântat ești cel ce semeni lângă toate apele,"]]],[33,[[1,"Vai de voi care distrugeți, dar nu ați fost distruși,"],[2,"Doamne, ai milă de noi. Te-am așteptat."],[3,"La zgomotul tunetului, popoarele au fugit."],[4,"Prada ta va fi adunată pe măsură ce omida se adună."],[5,"Domnul este înălțat, căci locuiește în înălțime."],[6,"Va exista stabilitate în vremurile tale, abundență de mântuire, înțelepciune și cunoaștere."],[7,"Iată, vitejii lor strigă afară;"],[8,"Autostrăzile sunt pustii."],[9,"Pământul plânge și lâncește."],[10,"„Acum mă voi ridica”, zice Domnul."],[11,"Vei concepe pleava."],[12,"Popoarele vor fi ca arderea varului,"],[13,"Ascultă, care ești departe, ce am făcut;"],[14,"Păcătoșii din Sion se tem."],[15,"Cel care umblă drept"],[16,"el va locui sus."],[17,"Ochii tăi îl vor vedea pe rege în frumusețea lui."],[18,"Inima ta va medita asupra terorii."],[19,"Nu vei mai vedea oamenii fioroși,"],[20,"Priviți la Sion, orașul sărbătorilor noastre stabilite."],[21,"Dar acolo Domnul va fi cu noi cu măreție,"],[22,"Căci Domnul este judecătorul nostru."],[23,"Tachelajul tău este dezlegat."],[24,"Locuitorul nu va spune: „Sunt bolnav”."]]],[34,[[1,"Apropiați-vă, națiuni, să auziți!"],[2,"Căci Domnul este mâniat împotriva tuturor neamurilor,"],[3,"Ucișii lor vor fi și ei izgoniți,"],[4,"Toată armata cerului va fi dizolvată."],[5,"Căci sabia mea și-a băut plin pe cer."],[6,"Sabia Domnului este plină de sânge."],[7,"Boii sălbatici vor coborî cu ei,"],[8,"Căci Domnul are o zi de răzbunare,"],[9,"Fluxurile sale vor fi transformate în smoală,"],[10,"Nu va fi stins noaptea sau ziua."],[11,"Dar pelicanul și porcul-spic îl vor poseda."],[12,"Îi vor chema pe nobilii săi în împărăție, dar nimeni nu va fi acolo;"],[13,"Spini vor apărea în palatele lui,"],[14,"Animalele sălbatice din deșert se vor întâlni cu lupii,"],[15,"Șarpele săgeată își va face cuib acolo,"],[16,"Căutați în cartea Domnului și citiți:"],[17,"El a tras la sorți pentru ei,"]]],[35,[[1,"Se vor bucura pustia si uscatul."],[2,"Va înflori din belșug,"],[3,"Întărește mâinile slabe,"],[4,"Spune-le celor care au o inimă înfricoșată: „Fiți puternici!"],[5,"Atunci se vor deschide ochii orbilor,"],[6,"Atunci șchiopul va sări ca o căprioară,"],[7,"Nisipul care arde va deveni un bazin,"],[8,"O autostradă va fi acolo, un drum,"],[9,"Nici un leu nu va fi acolo,"],[10,"Atunci cei răscumpărați ai Domnului se vor întoarce,"]]],[36,[[1,"În al patrusprezecelea an al împăratului Ezechia, Sanherib, împăratul Asiriei, a atacat toate cetățile întărite ale lui Iuda și le-a cucerit."],[2,"Regele Asiriei l-a trimis pe Rabşache de la Lachis la Ierusalim la împăratul Ezechia cu o armată mare. Stătea lângă apeductul din bazinul de sus, pe autostrada câmpului plinului."],[3,"Atunci au ieşit la el Eliachim, fiul lui Hilchia, căpetenia casei, şi Şebna cărturarul şi Ioah, fiul lui Asaf, scriitorul."],[4,"Rabşache le-a zis: „Spune-i acum lui Ezechia: „Marele împărat, regele Asiriei, spune: „Ce încredere este aceasta în care vă încredeţi?"],[5,"Eu spun că sfatul și puterea ta pentru război sunt doar cuvinte deșarte. Acum în cine te încrezi, că te-ai răzvrătit împotriva mea?"],[6,"Iată, te încrezi în toiagul acestei trestie zdrobită, chiar în Egipt, care, dacă se sprijină cineva de ea, îi va intra în mână și o va străpunge. Așa este Faraonul, regele Egiptului, pentru toți cei care se încred în el."],[7,"Dar dacă îmi spui: „Noi ne încredem în Domnul, Dumnezeul nostru”, nu este acesta acela ale cărui înălțimi și altare le-a luat Ezechia și a spus lui Iuda și Ierusalimului: „Să vă închinați înaintea acestui altar”?”"],[8,"Acum, te rog, fă un gaj stăpânului meu, regele Asiriei, și-ți voi da două mii de cai, dacă poți din partea ta să pui călăreți pe ei."],[9,"Cum deci poți întoarce fața unui căpitan dintre cei mai mici dintre slujitorii stăpânului meu și să te încrezi în Egipt pentru care și călăreți?"],[10,"M-am suit acum fără Domnul împotriva acestei țări ca să o distrug? Domnul mi-a zis: „Suie-te împotriva acestei țări și nimicește-o.”"],[11,"Atunci Eliachim, Şebna şi Ioah i-au spus lui Rabşache: \"Te rog, vorbeşte slujitorilor tăi în aramaică, căci noi înţelegem; nu ne vorbi în limba iudeilor, în auzul poporului care este pe zid\"."],[12,"Dar Rabşache a zis: „Oare m-a trimis stăpânul meu numai la stăpânul tău şi la tine, să spun aceste cuvinte, şi nu la oamenii care stau pe zid, care îşi vor mânca bălegarul şi îşi vor bea urina cu tine?”"],[13,"Atunci Rabşache s-a ridicat şi a strigat cu glas tare în limba iudeilor şi a zis: „Ascultaţi cuvintele marelui rege, regele Asiriei!"],[14,"Împăratul zice: „Să nu te înșele pe Ezechia; căci nu te va putea izbăvi."],[15,"Nu-l lăsa pe Ezechia să te facă să te încrezi în DOMNUL, spunând: „Domnul ne va izbăvi, și această cetate nu va fi dată în mâna împăratului Asiriei.”"],[16,"Nu-l asculta pe Ezechia, căci regele Asiriei zice: „Faceți pace cu mine și ieșiți la mine; și fiecare dintre voi să mănânce din vița lui și fiecare din smochinul său și fiecare dintre voi să bea apele cisternei sale;"],[17,"până voi veni și vă voi duce într-o țară ca țara voastră, o țară a grânelor și a vinului nou, o țară a pâinii și a viilor."],[18,"Ferește-te ca Ezechia să nu te convingă, zicând: „Domnul ne va izbăvi”. A eliberat vreunul dintre zeii națiunilor pământurile lor din mâna regelui Asiriei?"],[19,"Unde sunt zeii lui Hamat și Arpad? Unde sunt zeii lui Sepharvaim? Au eliberat ei Samaria din mâna mea?"],[20,"Cine sunt ei dintre toți dumnezeii acestor țări care și-au scăpat țara din mâna mea, ca Domnul să izbăvească Ierusalimul din mâna mea?”"],[21,"Dar ei au tăcut și nu au răspuns nimic, căci porunca împăratului era: „Nu-i răspunde”."],[22,"Atunci Eliachim, fiul lui Hilchia, căpetenia casei, și Șebna cărturarul și Ioah, fiul lui Asaf, scriitorul, au venit la Ezechia cu hainele rupte și i-au spus cuvintele lui Rabșache."]]],[37,[[1,"Când a auzit regele Ezechia, și-a sfâșiat hainele, s-a acoperit cu un sac și a intrat în casa Domnului."],[2,"El a trimis pe Eliachim, care era șeful casei, și pe Șebna, cărturarul și pe bătrânii preoților, acoperiți cu sac, la proorocul Isaia, fiul lui Amoț."],[3,"Ei i-au zis: „Iezechia spune: „Astăzi este o zi de necaz, de mustrare și de lepădare; căci copiii au ajuns la naștere și nu este putere să nască."],[4,"Poate că Domnul, Dumnezeul tău, va auzi cuvintele lui Rabşache, pe care împăratul Asiriei, stăpânul său, l-a trimis să sfideze Dumnezeul cel viu, şi să mustre cuvintele pe care le-a auzit Domnul Dumnezeul tău. De aceea, ridică-ți rugăciunea pentru rămășița care a mai rămas.”"],[5,"Astfel, slujitorii regelui Ezechia au venit la Isaia."],[6,"Isaia le-a zis: „Spuneți stăpânului vostru: „Domnul zice: „Nu vă temeți de cuvintele pe care le-ați auzit și cu care slujitorii împăratului Asiriei m-au hulit."],[7,"Iată, voi pune un duh în el și el va auzi vești și se va întoarce în țara lui. Îl voi face să cadă prin sabie în țara lui.”’”"],[8,"Atunci Rabşache s-a întors şi l-a găsit pe regele Asiriei luptând împotriva Libnei, pentru că a auzit că a plecat din Lachis."],[9,"El a auzit vestea despre Tirhaca, regele Etiopiei: „A ieșit să lupte împotriva ta”. Când a auzit, a trimis soli lui Ezechia, zicând:"],[10,"„Așa să-i spui lui Ezechia, împăratul lui Iuda, și să-i spui: „Nu lăsa să te înșele Dumnezeul tău, în care te încrezi, zicând: „Ierusalimul nu va fi dat în mâna împăratului Asiriei”."],[11,"Iată, ați auzit ce au făcut împărații Asiriei tuturor țărilor, distrugându-le cu totul. Vei fi livrat?"],[12,"Oare i-au izbăvit zeii neamurilor, pe care părinţii mei le-au nimicit, pe Gozan, Haran, Reţef şi pe copiii Edenului care erau în Telasar?"],[13,"Unde este regele Hamatului și regele Arpadului și regele cetății Sefarvaim, Hena și Iva?"],[14,"Ezechia a primit scrisoarea din mâna solilor și a citit-o. Atunci Ezechia s-a suit la casa Domnului și a întins-o înaintea Domnului."],[15,"Ezechia s-a rugat Domnului, zicând:"],[16,"„Domnul oștirilor, Dumnezeul lui Israel, care tronează printre heruvimi, Tu ești Dumnezeul tuturor împărățiilor pământului, Tu ai făcut cerurile și pământul."],[17,"Întoarce-ți urechea, Doamne, și ascultă. Deschide-ți ochii, Doamne, și iată. Ascultă toate cuvintele lui Sanherib, care a trimis să sfideze pe Dumnezeul cel viu."],[18,"Cu adevărat, Doamne, împărații Asiriei au nimicit toate țările și țara lor,"],[19,"și și-au aruncat zeii în foc; pentru că nu erau zei, ci lucrarea mâinilor oamenilor, lemn și piatră; de aceea i-au nimicit."],[20,"Acum, Doamne, Dumnezeul nostru, izbăvește-ne din mâna Lui, pentru ca toate împărățiile pământului să cunoască că Tu ești DOMNUL, numai Tu.”"],[21,"Atunci Isaia, fiul lui Amot, a trimis la Ezechia să-i spună: „Doamne, Dumnezeul lui Israel zice: „Pentru că m-ai rugat împotriva lui Sanherib, regele Asiriei,"],[22,"Acesta este cuvântul pe care l-a rostit Domnul despre el: Fecioara, fiica Sionului, te-a disprețuit și te-a batjocorit. Fiica Ierusalimului a clătinat din cap la tine."],[23,"Pe cine ai sfidat și hulit? Împotriva cui ți-ai înălțat glasul și ți-ai ridicat ochii în sus? Împotriva Sfântului lui Israel."],[24,"Prin slujitorii tăi, l-ai sfidat pe Domnul și ai zis: „Cu mulțimea carelor mele am urcat până la înălțimea munților, până la adâncimile Libanului, îi voi tăia cedrii înalți și chiparoșii lui frumoși și voi intra în înălțimea lui cea mai îndepărtată, în pădurea câmpului său roditor."],[25,"Am săpat și am băut apă și cu talpa picioarelor mele voi seca toate râurile Egiptului.”"],[26,"„N-ai auzit cum am făcut-o cu mult timp în urmă și cum am făcut-o în vremuri străvechi? Acum am făcut-o să se întâmple, ca să fie a ta să distrugi cetățile întărite, prefăcându-le în mormane de ruine."],[27,"Prin urmare, locuitorii lor aveau puțină putere. Au fost consternați și confuzi. Erau ca iarba câmpului și ca iarba verde, ca iarba de pe acoperișuri și ca un câmp înainte ca roadele să-i fi crescut."],[28,"Dar știu că stai jos, ieși, intri și ești furios împotriva mea."],[29,"Din cauza mâniei tale împotriva mea și pentru că trufia ta mi s-a urcat la urechi, de aceea îmi voi pune cârligul în nasul tău și frâul meu în buzele tale și te voi întoarce înapoi pe calea pe care ai venit."],[30,"„‘Acesta vă va fi semnul: veți mânca în acest an din ce va crește de la sine și în al doilea an din ce va izvora; și în al treilea an să semănați, să secerați, să sădiți vii și să mâncați rodul lor."],[31,"Rămășița care a scăpat din casa lui Iuda va prinde din nou rădăcini în jos și va aduce rod în sus."],[32,"Căci din Ierusalim o rămășiță va ieși și supraviețuitorii vor scăpa de pe muntele Sionului. Răvna Domnului oștirilor va împlini aceasta.”"],[33,"„De aceea, Domnul spune despre regele Asiriei: „El nu va veni în această cetate, nu va arunca acolo săgeată, nu va veni înaintea ei cu scut și nu va ridica o movilă împotriva ei."],[34,"Se va întoarce pe calea pe care a venit și nu va veni în această cetate, zice Domnul."],[35,"„Căci voi apăra această cetate ca să o salvez, de dragul meu și de dragul robului meu David.”"],[36,"Atunci îngerul Domnului a ieșit și a lovit o sută optzeci și cinci de mii de oameni în tabăra asirienilor. Când oamenii s-au sculat dis-de-dimineață, iată, acestea erau toate cadavre."],[37,"Deci Sanherib, regele Asiriei, a plecat, a plecat, s-a întors la Ninive și a rămas acolo."],[38,"Pe când se închina în casa zeului său Nisroc, fiii lui Adramelec și Șarezer l-au lovit cu sabia; şi au scăpat în ţara Ararat. În locul lui a domnit fiul său Esar Hadon."]]],[38,[[1,"În acele zile, Ezechia era bolnav și aproape de moarte. Proorocul Isaia, fiul lui Amot, a venit la el și i-a zis: „Domnul zice: „Pune-ți casa în ordine, căci vei muri și nu vei trăi.”"],[2,"Atunci Ezechia și-a întors fața spre zid și s-a rugat Domnului:"],[3,"și a zis: „Adu-ți aminte acum, Doamne, că te implor că am umblat înaintea Ta în adevăr și cu o inimă desăvârșită și am făcut ce este bine înaintea Ta.” Atunci Ezechia a plâns amar."],[4,"Atunci cuvântul Domnului a venit la Isaia, zicând:"],[5,"„Du-te și spune lui Ezechia: „Domnul, Dumnezeul lui David, tatăl tău, zice: „Am auzit rugăciunea ta. Ți-am văzut lacrimile. Iată, voi adăuga cincisprezece ani la viața ta."],[6,"Te voi elibera pe tine și această cetate din mâna împăratului Asiriei și voi apăra această cetate."],[7,"Acesta va fi semnul pentru voi de la Domnul, că Domnul va face lucrul acesta pe care a spus-o."],[8,"Iată, voi face umbra cadranului solar, care s-a apus pe ceasul lui Ahaz odată cu soarele, să se întoarcă înapoi cu zece trepte.”’” Așa că soarele s-a întors cu zece pași pe cadranul solar pe care se apusese."],[9,"Scrierea lui Ezechia, regele lui Iuda, când fusese bolnav și și-a vindecat boala:"],[10,"Am spus: „În mijlocul vieții mele intru pe porțile mormântului."],[11,"Am spus: „Nu voi vedea pe Domnul,"],[12,"Locuința mea este îndepărtată,"],[13,"Am așteptat cu răbdare până dimineața."],[14,"Am trăncănit ca o rândunică sau ca o macara."],[15,"ce voi spune?"],[16,"Doamne, oamenii trăiesc prin aceste lucruri;"],[17,"Iată, pentru pace am avut mare suferință,"],[18,"Căci Sheolul nu te poate lauda."],[19,"Cel viu, cel viu, El te va lăuda, așa cum fac eu astăzi."],[20,"Domnul mă va mântui."],[21,"Isaia spusese: „Să ia o turtă cu smochine și să o pună ca cataplasmă pe furuncul și se va vindeca”."],[22,"Ezechia mai spusese: „Care este semnul că mă voi sui la casa Domnului?”"]]],[39,[[1,"În vremea aceea, Merodac-Baladan, fiul lui Baladan, regele Babilonului, a trimis scrisori și un dar lui Ezechia, pentru că a auzit că a fost bolnav și s-a vindecat."],[2,"Ezechia a fost mulțumit de ei și le-a arătat casa lucrurilor lui scumpe, argintul, aurul, mirodeniile și untdelemnul prețios și toată casa armurii lui și tot ce se găsea în comorile lui. Nu era nimic în casa lui și nici în toată stăpânirea lui, ceea ce Ezechia nu le-a arătat."],[3,"Atunci proorocul Isaia a venit la regele Ezechia și l-a întrebat: „Ce au spus acești oameni? De unde au venit la tine?”"],[4,"Apoi a întrebat: „Ce au văzut în casa ta?”"],[5,"Atunci Isaia a zis lui Ezechia: „Ascultă cuvântul Domnului oștirilor:"],[6,"„Iată, vin zile când tot ce este în casa ta și ceea ce au strâns părinţii tăi până astăzi, va fi dus în Babilon. Nimic nu va rămâne, zice Domnul."],[7,"„Îți vor lua pe fiii tăi care vor ieși din tine, pe care îi vei avea ca naștere, și vor fi fameni în palatul împăratului Babilonului.”"],[8,"Atunci Ezechia a zis lui Isaia: „Cuvântul Domnului pe care l-ai rostit este bun”. El a mai spus: „Căci va fi pace și adevăr în zilele mele”."]]],[40,[[1,"„Mângâie, mângâie poporul meu”, spune Dumnezeul tău."],[2,"„Vorbește cu mângâiere Ierusalimului și strigă-i că războiul ei s-a încheiat, că nelegiuirea ei este iertată, că a primit din mâna Domnului dublu pentru toate păcatele ei.”"],[3,"Glasul celui care strigă,"],[4,"Fiecare vale va fi înălțată,"],[5,"Slava Domnului va fi descoperită,"],[6,"Vocea unuia care spune: „Strigă!”"],[7,"Iarba se ofilește,"],[8,"Iarba se ofilește,"],[9,"Tu care spui Sionului vești bune, urcă-te pe un munte înalt."],[10,"Iată, Domnul, Domnul, va veni ca un puternic,"],[11,"El își va păște turma ca un păstor."],[12,"Care a măsurat apele în adâncul mâinii sale,"],[13,"Care a îndreptat Duhul Domnului,"],[14,"Cu cine s-a sfătuit,"],[15,"Iată, națiunile sunt ca o picătură într-o găleată,"],[16,"Libanul nu este suficient pentru a arde,"],[17,"Toate neamurile sunt ca nimic înaintea lui."],[18,"Atunci cu cine îl vei asemăna pe Dumnezeu?"],[19,"Un muncitor a turnat o imagine,"],[20,"Cel care este prea sărac pentru o astfel de ofrandă alege un copac care nu va putrezi."],[21,"nu ai stiut?"],[22,"El este cel care stă deasupra cercului pământului,"],[23,"care aduce prinți la nimic,"],[24,"Sunt plantate abia."],[25,"„Atunci cu cine mă vei asemăna?"],[26,"Ridică-ți ochii sus,"],[27,"De ce spui, Iacob,"],[28,"nu ai stiut?"],[29,"El dă putere celor slabi."],[30,"Chiar și tinerii leșin și obosesc,"],[31,"dar cei ce așteaptă pe Domnul își vor reînnoi puterea."]]],[41,[[1,"„Taceți în fața mea, insule,"],[2,"Cine a ridicat unul din est?"],[3,"El îi urmărește"],[4,"Cine a lucrat și a făcut-o,"],[5,"Insulele au văzut și se tem."],[6,"Fiecare își ajută aproapele."],[7,"Așa că dulgherul îl încurajează pe aurar."],[8,"„Dar tu, Israele, robul meu,"],[9,"pe tine pe care te-am strâns de la marginile pământului,"],[10,"Nu-ți fie frică, căci Eu sunt cu tine."],[11,"Iată, toți cei care se înfurie împotriva ta vor fi dezamăgiți și încurcați."],[12,"Le vei căuta și nu le vei găsi,"],[13,"Căci Eu, Domnul Dumnezeul tău, te voi ține de mâna dreaptă,"],[14,"Nu te teme, vierme Iacob,"],[15,"Iată, am făcut din tine un nou instrument de treierat ascuțit, cu dinți."],[16,"Le vei strânge,"],[17,"Săracii și nevoiașii caută apă și nu există."],[18,"Voi deschide râuri pe înălțimile goale,"],[19,"Voi pune cedru, salcâm, mirt și pomi de ulei în pustie."],[20,"ca să vadă, să cunoască, să se gândească și să înțeleagă împreună,"],[21,"Produceți-vă cauza”, zice Domnul."],[22,"„Să ne anunțe și să ne declare ce se va întâmpla!"],[23,"Declară lucrurile care vor veni în continuare,"],[24,"Iată, nu ești nimic,"],[25,"„Am ridicat unul de la miazănoapte și el a venit,"],[26,"Cine a declarat-o de la început, ca să știm?"],[27,"Eu sunt primul care i-a spus Sionului: ‘Iată, uită-te la ei’;"],[28,"Când mă uit, nu există bărbat,"],[29,"Iată, toate faptele lor sunt deșertăciune și nimic."]]],[42,[[1,"„Iată, robul meu, pe care îl susțin,"],[2,"El nu va striga,"],[3,"El nu va sparge o trestie învinețită."],[4,"El nu va eșua și nu va fi descurajat,"],[5,"Dumnezeul Iahve,"],[6,"„Eu, Domnul, te-am chemat în dreptate."],[7,"a deschide ochii orbi,"],[8,"„Eu sunt Iehova."],[9,"Iată, lucrurile dintâi s-au întâmplat"],[10,"Cântați Domnului un cântec nou,"],[11,"Sălbăticia și cetățile ei să-și ridice glasul,"],[12,"Să dea slavă Domnului,"],[13,"Domnul va ieși ca un om puternic."],[14,"„Am tăcut mult timp."],[15,"Voi nimici munți și dealuri,"],[16,"Îi voi aduce pe orbi pe o cale pe care ei nu o cunosc."],[17,"„Cei care se încred în imaginile gravate,"],[18,"„Auzi, surd,"],[19,"Cine este orb, decât robul meu?"],[20,"Vezi multe lucruri, dar nu observi."],[21,"I-a plăcut Domnului, de dragul dreptății Lui, să mărească Legea"],[22,"Dar acesta este un popor jefuit și jefuit."],[23,"Cine este printre voi care să asculte de aceasta?"],[24,"Care l-a dat pe Iacov drept pradă,"],[25,"De aceea și-a revărsat asupra lui aprinsul mâniei sale,"]]],[43,[[1,"Dar acum DOMNUL care te-a creat, Iacob,"],[2,"Când vei trece prin ape, voi fi cu tine,"],[3,"Căci eu sunt Domnul Dumnezeul tău,"],[4,"Din moment ce ai fost prețios și onorat înaintea mea,"],[5,"Nu-ți fie frică, căci Eu sunt cu tine."],[6,"Voi spune nordului: „Renunță la ei!”"],[7,"oricine este chemat pe numele meu,"],[8,"Scoate-i pe orbii care au ochi,"],[9,"Să se strângă toate neamurile,"],[10,"„Voi sunteți martorii Mei”, zice Domnul,"],[11,"Eu însumi sunt Iehova."],[12,"Am declarat, am mântuit și am arătat,"],[13,"Da, de când era ziua, eu sunt el."],[14,"Domnul, Răscumpărătorul tău, Sfântul lui Israel spune: „Pentru tine, am trimis în Babilon și îi voi doborî pe toți ca fugari, chiar și pe caldeeni, în corăbiile veseliei lor."],[15,"Eu sunt Domnul, Sfântul tău, Creatorul lui Israel, Regele tău.”"],[16,"DOMNUL, care-ți face cale în mare,"],[17,"care scoate carul și calul,"],[18,"„Nu-ți amintești de lucrurile anterioare,"],[19,"Iată, voi face un lucru nou."],[20,"Animalele câmpului, şacalii şi struţii mă vor cinsti,"],[21,"oamenii pe care i-am format pentru mine,"],[22,"Dar tu nu M-ai chemat, Iacob;"],[23,"Nu mi-ai adus nici o oaie pentru arderile de tot,"],[24,"Nu mi-ai cumpărat niciun baston dulce cu bani,"],[25,"Eu, chiar eu, sunt cel care șterg fărădelegile tale pentru mine;"],[26,"Pune-mă în amintire."],[27,"Primul tău tată a păcătuit,"],[28,"De aceea voi pângări pe căpeteniile sanctuarului;"]]],[44,[[1,"Dar ascultă acum, Iacob, robul meu,"],[2,"Iată ce te-a făcut Domnul,"],[3,"Căci voi turna apă peste cel însetat,"],[4,"și vor răsări printre iarbă,"],[5,"Unul va spune: „Eu sunt al Domnului”."],[6,"Aceasta este ceea ce Domnul, regele lui Israel,"],[7,"Cine este ca mine?"],[8,"Nu te teme,"],[9,"Oricine face o imagine sculptată este zadarnic."],[10,"Cine a modelat un zeu,"],[11,"Iată, toţi semenii lui vor fi dezamăgiţi;"],[12,"Fierarul ia un topor,"],[13,"Tâmplarul întinde o linie."],[14,"El tăie cedri pentru sine,"],[15,"Atunci va fi ca un om să ardă;"],[16,"El arde o parte din ea în foc."],[17,"Restul îl transformă într-un zeu,"],[18,"Ei nu știu, nici nu iau în considerare,"],[19,"Nimeni nu se gândește,"],[20,"Se hrănește cu cenușă."],[21,"Aduceți-vă aminte de aceste lucruri, Iacov și Israel,"],[22,"Am șters, ca un nor gros, fărădelegile tale,"],[23,"Cântaţi, ceruri, căci Domnul a făcut-o!"],[24,"Domnul, Răscumpărătorul tău,"],[25,"care zădărnicește semnele mincinoșilor,"],[26,"care confirmă cuvântul slujitorului său,"],[27,"care zice adâncului: „Fii uscat!”"],[28,"care spune despre Cirus: „El este păstorul meu și îmi va îndeplini toate plăcerile”"]]],[45,[[1,"Domnul zice unsului Său, lui Cir, a cărui mână dreaptă am ținut-o ca să supună neamurile înaintea lui și să le dezbrace pe împărați armurile, să deschidă ușile înaintea lui și porțile să nu fie închise:"],[2,"„Voi merge înaintea ta"],[3,"Îți voi da comorile întunericului"],[4,"De dragul robului meu Iacov,"],[5,"Eu sunt Domnul și nu este nimeni altcineva."],[6,"ca să știe de la răsăritul soarelui,"],[7,"Formez lumina"],[8,"Ploaie, ceruri, de sus,"],[9,"Vai de cel ce se luptă cu Făcătorul său,"],[10,"Vai de cel care zice unui tată: „De ce ai devenit tată?”"],[11,"Domnul, Sfântul lui Israel"],[12,"Eu am făcut pământul și am creat omul pe el."],[13,"L-am ridicat în dreptate,"],[14,"Domnul spune: „Munca Egiptului,"],[15,"Cu siguranță ești un Dumnezeu care te-a ascuns,"],[16,"Vor fi dezamăgiți,"],[17,"Israel va fi mântuit de Domnul cu o mântuire veșnică."],[18,"Pentru Domnul, care a creat cerurile,"],[19,"Nu am vorbit în secret,"],[20,"„Adunați-vă și veniți."],[21,"Declarați și prezentați-l."],[22,"„Priviți la Mine și fiți mântuiți, toate marginile pământului;"],[23,"Am jurat pe mine."],[24,"Vor spune despre mine,"],[25,"Toți urmașii lui Israel vor fi neprihăniți în Domnul,"]]],[46,[[1,"Bel se înclină."],[2,"Se aplecă și se închină împreună."],[3,"„Ascultă-mă, casa lui Iacov,"],[4,"Chiar și până la bătrânețe sunt el,"],[5,"„Cu cine mă vei compara și vei considera egalul meu,"],[6,"Unii varsă aur din pungă,"],[7,"Îl poartă pe umăr."],[8,"„Amintiți-vă de aceasta și arătați-vă oameni."],[9,"Adu-ți aminte de lucrurile de odinioară;"],[10,"Declar sfârşitul de la început,"],[11,"Eu numesc o pasăre răpitoare din est,"],[12,"Ascultă-mă, inimă încăpățânată,"],[13,"Îmi aduc dreptatea aproape."]]],[47,[[1,"„Coboară și așează-te în țărână, fecioară fiică a Babilonului."],[2,"Luați pietrele de moară și măcinați făina."],[3,"Goliciunea ta va fi descoperită."],[4,"Răscumpărătorul nostru, Domnul armatelor este numele lui,"],[5,"„Stai în tăcere și du-te în întuneric,"],[6,"Eram supărat pe oamenii mei."],[7,"Ai spus: „Voi fi o prințesă pentru totdeauna”."],[8,"„Acum, deci, ascultați aceasta, voi cei dăruiți plăcerilor,"],[9,"Dar aceste două lucruri vă vor veni într-un moment într-o zi:"],[10,"Căci te-ai încrezut în răutatea ta."],[11,"Prin urmare, dezastrul va veni asupra ta."],[12,"„Stă acum cu descântecele tale"],[13,"Ești obosit de mulțimea sfaturilor tale."],[14,"Iată, sunt ca miriștea."],[15,"Lucrurile la care ai muncit vor fi astfel:"]]],[48,[[1,"„Ascultă aceasta, casa lui Iacov,"],[2,"căci ei se numesc cetățeni ai orașului sfânt,"],[3,"Am declarat lucrurile din trecut."],[4,"Pentru că știam că ești obstinat,"],[5,"de aceea v-am spus-o din vechime;"],[6,"L-ai auzit."],[7,"Ele sunt create acum, și nu din vechime."],[8,"Da, nu ai auzit."],[9,"Pentru numele meu, îmi voi amâna mânia,"],[10,"Iată, te-am rafinat,"],[11,"De dragul meu,"],[12,"„Ascultă-mă, Iacob,"],[13,"Da, mâna mea a pus temelia pământului,"],[14,"„Adunați-vă, toți, și ascultați!"],[15,"Eu, chiar și eu, am vorbit."],[16,"„Apropie-te de mine și auzi asta:"],[17,"Iahve,"],[18,"O, dacă ai fi ascultat de poruncile mele!"],[19,"De asemenea, urmașii tăi ar fi fost ca nisipul"],[20,"Părăsiți Babilonul!"],[21,"Nu le-a fost sete când el i-a condus prin pustii."],[22,"„Nu este pace”, zice Domnul, „pentru cei răi”."]]],[49,[[1,"Ascultă-mă, insule."],[2,"El mi-a făcut gura ca o sabie ascuțită."],[3,"El mi-a spus: „Tu ești slujitorul meu,"],[4,"Dar eu am spus: „Degeaba am muncit."],[5,"Acum, DOMNUL, Cel care m-a format din pântece ca să-i fiu robul,"],[6,"Într-adevăr, el spune: „Este un lucru prea ușor să fii slujitorul meu ca să ridici semințiile lui Iacov,"],[7,"Domnul, Răscumpărătorul lui Israel și Sfântul Lui,"],[8,"Domnul spune: „Ți-am răspuns într-un timp potrivit."],[9,"spunând celor legați: „Ieșiți afară!”;"],[10,"Ei nu vor flămânzi, nici nu vor înseta;"],[11,"Voi face din toți munții mei un drum,"],[12,"Iată, acestea vor veni de departe,"],[13,"Cântați, ceruri, și bucurați-vă, pământ!"],[14,"Dar Sionul a zis: „Domnul m-a părăsit,"],[15,"„Poate o femeie să-și uite copilul care alăptează,"],[16,"Iată, te-am gravat pe palmele mâinilor mele."],[17,"Copiii tăi se grăbesc."],[18,"Ridică-ți ochii de jur împrejur și vezi:"],[19,"„Căci, în ceea ce privește pustiul tău și locurile tale pustii,"],[20,"Copiii suferinței tale vor spune în urechile tale:"],[21,"Atunci vei spune în inima ta: „Cine mi-a zămislit acestea, de când am fost lipsită de copiii mei?"],[22,"Domnul Domnul zice: „Iată, îmi voi ridica mâna către neamuri,"],[23,"Regii vor fi părinții tăi adoptivi,"],[24,"Să fie luat prada celor puternici,"],[25,"Dar Domnul zice: „Până și robii celor puternici vor fi luați,"],[26,"Îi voi hrăni cu trupul lor pe cei ce vă asupresc;"]]],[50,[[1,"Domnul zice: „Unde este actul de divorț al mamei tale, cu care am dat-o afară?"],[2,"De ce, când am venit, nu era nimeni?"],[3,"Îmbrăc cerurile cu întuneric."],[4,"Domnul Domnul mi-a dat limba celor ce sunt învățați,"],[5,"Domnul Domnul mi-a deschis urechea."],[6,"Le-am dat spatele celor care m-au bătut,"],[7,"Căci Domnul, Domnul, mă va ajuta."],[8,"Cel care mă îndreptățește este aproape."],[9,"Iată, Domnul, Domnul, mă va ajuta!"],[10,"Cine dintre voi se teme de Domnul"],[11,"Iată, voi toți cei ce aprindeți focul,"]]],[51,[[1,"„Ascultați-mă, voi care urmați dreptatea,"],[2,"Privește la Avraam, tatăl tău,"],[3,"Căci Domnul a mângâiat Sionul."],[4,"„Ascultă-mă, poporul meu;"],[5,"Dreptatea mea este aproape."],[6,"Ridică-ți ochii spre ceruri,"],[7,"„Ascultați-mă, cei ce cunoașteți dreptatea,"],[8,"Căci molia îi va mânca ca pe o haină,"],[9,"Trezește-te, trezește-te, îmbracă-te cu putere, brațul Domnului!"],[10,"Nu tu ai secat marea,"],[11,"Cei răscumpărați de Domnul se vor întoarce,"],[12,"„Eu, chiar eu, sunt cel care te mângâie."],[13,"Ai uitat pe Domnul, Făcătorul tău,"],[14,"Exilatul captiv va fi eliberat rapid."],[15,"Căci Eu sunt Domnul, Dumnezeul tău, care stârnesc marea"],[16,"Mi-am pus cuvintele în gura ta"],[17,"Treaz, treaz!"],[18,"Nu este nimeni care să o călăuzească printre toți fiii cărora ea i-a născut;"],[19,"Aceste două lucruri ți s-au întâmplat..."],[20,"Fiii tăi au leșinat."],[21,"Așadar, acum, auziți aceasta, nenorociți,"],[22,"Domnul tău, Iehova,"],[23,"O voi pune în mâna celor ce te chinuie,"]]],[52,[[1,"Treaz, treaz! Îmbrăcă-te cu puterea ta, Sion."],[2,"Scutura-te de praf!"],[3,"Căci Domnul zice: „Degeaba ai fost vândut;"],[4,"Căci Domnul Iehova zice:"],[5,"„Acum, deci, ce să fac aici”, zice Domnul,"],[6,"De aceea poporul meu va cunoaste numele meu."],[7,"Ce frumoase sunt picioarele celui ce aduce vești bune pe munți,"],[8,"Paznicii tăi ridică vocea."],[9,"Izbucnește în bucurie!"],[10,"Domnul și-a dezgolit brațul sfânt în ochii tuturor neamurilor."],[11,"Pleacă! Pleacă! Ieși de acolo! Nu atingeți nimic necurat!"],[12,"Căci nu vei ieşi în grabă,"],[13,"Iată, slujitorul meu se va comporta cu înțelepciune."],[14,"La fel și mulți au fost uimiți de tine..."],[15,"așa că va curăța multe neamuri."]]],[53,[[1,"Cine a crezut mesajul nostru?"],[2,"Căci el a crescut înaintea lui ca o plantă fragedă,"],[3,"Era disprețuit"],[4,"Cu siguranță el a suportat boala noastră"],[5,"Dar el a fost străpuns pentru fărădelegile noastre."],[6,"Toți ne plac oile s-au rătăcit."],[7,"A fost asuprit,"],[8,"El a fost luat de opresiune și judecată."],[9,"I-au făcut mormântul cu cei răi,"],[10,"Cu toate acestea, a plăcut Domnului să-l zdrobească."],[11,"După suferința sufletului său,"],[12,"De aceea îi voi da o parte cu cei mari."]]],[54,[[1,"„Cântă, stearpă, tu care n-ai născut!"],[2,"„Mărește locul cortului tău,"],[3,"Căci te vei întinde la dreapta și la stânga;"],[4,"„Nu vă temeți, căci nu vă veți fi rușine."],[5,"Căci Făcătorul tău este soțul tău; Domnul armatelor este numele lui."],[6,"Căci Domnul te-a chemat ca pe o soție părăsită și întristată în duh,"],[7,"„Pentru o clipă te-am părăsit,"],[8,"Într-o mânie debordantă, mi-am ascuns fața de tine pentru o clipă,"],[9,"„Căci aceasta este ca apele lui Noe pentru mine;"],[10,"Căci munții pot pleca,"],[11,"„Tu ai chinuit, zvâcniți de furtuni și nu mângâiați,"],[12,"Îți voi face vârfurile din rubine,"],[13,"Toți copiii tăi vor fi învățați de Domnul,"],[14,"Vei fi întărit în dreptate."],[15,"Iată, se pot aduna, dar nu lângă mine."],[16,"„Iată, am creat fierarul care aprinde cărbunii în flacără,"],[17,"Nicio armă care este formată împotriva ta nu va birui;"]]],[55,[[1,"„Hei! Veniți, toți cei care sunt însetați, la ape!"],[2,"De ce cheltuiți bani pentru ceea ce nu este pâine,"],[3,"Întoarce-ți urechea și vino la mine."],[4,"Iată, l-am dat drept martor popoarelor,"],[5,"Iată, vei chema un neam pe care nu-l cunoști;"],[6,"Căutați pe Domnul câtă vreme poate fi găsit."],[7,"Să-și părăsească calea cel rău,"],[8,"„Pentru că gândurile mele nu sunt gândurile tale,"],[9,"„Căci după cum cerurile sunt mai sus decât pământul,"],[10,"Căci cum ploaia coboară și zăpada din cer,"],[11,"așa este cuvântul meu care iese din gura mea:"],[12,"Căci vei ieși cu bucurie,"],[13,"În locul spinului se va ridica chiparosul;"]]],[56,[[1,"Domnul spune:"],[2,"Ferice de omul care face aceasta,"],[3,"Niciun străin care s-a unit cu Domnul să nu vorbească, zicând:"],[4,"Căci Domnul zice: „Famenilor care păzesc Sabatul Meu,"],[5,"Le voi da în casa mea și în zidurile mele o pomenire și un nume mai bun decât al fiilor și al fiicelor."],[6,"De asemenea, străinii care se unesc cu Domnul"],[7,"Le voi aduce pe acestea pe muntele meu sfânt,"],[8,"Domnul DOMNUL, care adună pe cei alungați ai lui Israel, zice:"],[9,"Toate animalele câmpului,"],[10,"Paznicii lui sunt orbi."],[11,"Da, câinii sunt lacomi."],[12,"„Vino”, spun ei, „voi lua vin,"]]],[57,[[1,"Cei neprihăniți pier,"],[2,"El intră în pace."],[3,"„Dar apropiați-vă de aici, fii ai vrăjitoarei,"],[4,"De cine batjocoriti?"],[5,"voi care vă înflăcărați printre stejari,"],[6,"Printre pietrele netede ale văii se află porțiunea ta."],[7,"Pe un munte înalt și înalt ți-ai așezat patul."],[8,"Ți-ai așezat memorialul în spatele ușilor și stâlpilor,"],[9,"Te-ai dus la rege cu ulei,"],[10,"Erai obosit de lungimea căilor tale;"],[11,"„De cine te-ai temut și te-ai temut,"],[12,"Voi vesti dreptatea ta;"],[13,"Când plângi,"],[14,"El va spune: „Clădiți, zidiți, pregătiți calea!"],[15,"Pentru Cel înalt și înalt care locuiește în veșnicie,"],[16,"Căci nu mă voi certa pentru totdeauna, nici nu mă voi mânia mereu;"],[17,"M-am supărat din cauza nelegiuirii lăcomiei lui și l-am lovit."],[18,"I-am văzut căile și-l voi vindeca."],[19,"Eu creez fructul buzelor:"],[20,"Dar cei răi sunt ca marea tulburată;"],[21,"„Nu este pace”, spune Dumnezeul meu,"]]],[58,[[1,"„Plângeți cu voce tare! Nu cruța!"],[2,"Dar ei mă caută zilnic,"],[3,"„De ce am postit”, spun ei, „și nu vezi?"],[4,"Iată, postești pentru ceartă și ceartă,"],[5,"Acesta este postul pe care l-am ales?"],[6,"„Nu acesta este postul pe care l-am ales:"],[7,"Nu este să-ți împarți pâinea celor flămând,"],[8,"Atunci lumina ta va izbucni ca dimineața,"],[9,"Atunci vei chema și Domnul va răspunde."],[10,"iar dacă vă revărsați sufletul celui flămând,"],[11,"și Domnul te va călăuzi mereu,"],[12,"Cei care vor fi dintre voi vor construi vechile pustii."],[13,"„Dacă întorci piciorul de la Sabat,"],[14,"atunci te vei desfăta în Domnul,"]]],[59,[[1,"Iată, mâna Domnului nu este scurtată, ca să nu poată mântui;"],[2,"Dar fărădelegile tale te-au despărțit de Dumnezeul tău,"],[3,"Căci mâinile tale sunt spurcate cu sânge,"],[4,"Nimeni nu dă în judecată în dreptate,"],[5,"Ei clocesc ouă de viperă"],[6,"Pânzele lor nu vor deveni haine."],[7,"Picioarele lor aleargă spre rău,"],[8,"Ei nu cunosc calea păcii;"],[9,"De aceea dreptatea este departe de noi,"],[10,"Bâjbâim după perete ca orbii."],[11,"Toți răcnim ca urșii"],[12,"Căci fărădelegile noastre sunt înmulțite înaintea ta,"],[13,"călcând și tăgăduind pe Domnul,"],[14,"Dreptatea este întoarsă înapoi,"],[15,"Da, adevărul lipsește;"],[16,"El a văzut că nu era niciun om,"],[17,"El a îmbrăcat dreptatea ca pe o platoșă,"],[18,"Conform faptelor lor,"],[19,"Deci se vor teme de numele Domnului din apus,"],[20,"„Un Răscumpărător va veni în Sion,"],[21,"„În ceea ce mă privește, acesta este legământul Meu cu ei”, zice Domnul. „Duhul Meu, care este peste tine, și cuvintele Mele pe care le-am pus în gura ta, nu se vor ieși din gura ta, nici din gura sămânțării tale, nici din gura sămânțălui tău”, zice Domnul, „de acum înainte și în veci”."]]],[60,[[1,"„Scoală-te, strălucește, căci lumina ta a venit,"],[2,"Căci iată, întunericul va acoperi pământul,"],[3,"Națiunile vor veni la lumina ta,"],[4,"„Ridică-ți ochii de jur împrejur și vezi:"],[5,"Atunci vei vedea și vei fi strălucitor,"],[6,"O mulțime de cămile te va acoperi,"],[7,"Toate turmele din Chedar se vor aduna la tine."],[8,"„Cine sunt aceștia care zboară ca un nor,"],[9,"Cu siguranță insulele mă vor aștepta,"],[10,"„Străinii îți vor zidi zidurile,"],[11,"De asemenea, porțile voastre vor fi deschise mereu; nu vor fi închise zi și noapte, ca oamenii să vă aducă bogăția neamurilor și împărații lor duși în robie."],[12,"Căci națiunea și împărăția aceea care nu vă vor sluji vor pieri; da, acele neamuri vor fi complet risipite."],[13,"„Slava Libanului va veni la tine, chiparosul, pinul și buisul împreună, pentru a înfrumuseța locul locașului meu sfânt; și voi face slavă locul picioarelor Mele."],[14,"Fiii celor ce te-au chinuit se vor închina înaintea ta;"],[15,"„În vreme ce ați fost părăsiți și urâți,"],[16,"Vei bea și laptele neamurilor,"],[17,"Pentru bronz voi aduce aur;"],[18,"Nu se va mai auzi violență în țara ta,"],[19,"Soarele nu va mai fi lumina ta ziua,"],[20,"Soarele tău nu va mai apune,"],[21,"Atunci poporul tău va fi toți drepți."],[22,"Cel mic va deveni o mie,"]]],[61,[[1,"Duhul Domnului Iehova este peste mine,"],[2,"pentru a vesti anul favoării Domnului"],[3,"pentru a avea grijă de cei ce plâng în Sion,"],[4,"Vor reconstrui vechile ruine."],[5,"Străinii vor sta și vor hrăni turmele voastre."],[6,"Dar voi veți fi numiți preoți ai Domnului."],[7,"În loc de rușine, vei avea dublu."],[8,"„Căci eu, Domnul, iubesc dreptatea."],[9,"Neamul lor va fi cunoscut printre neamuri,"],[10,"Mă voi bucura foarte mult în Domnul!"],[11,"Căci așa cum pământul își produce mugurii,"]]],[62,[[1,"De dragul Sionului nu voi tace,"],[2,"Neamurile vor vedea dreptatea Ta,"],[3,"Vei fi și o cunună de frumusețe în mâna Domnului,"],[4,"Nu vei mai fi numit Parasit,"],[5,"Căci precum un tânăr se căsătorește cu o fecioară,"],[6,"Am pus străjeri pe zidurile tale, Ierusalim."],[7,"și să nu-i dai odihnă până nu se va întări,"],[8,"Domnul a jurat pe mâna Sa dreaptă,"],[9,"dar cei ce l-au secerat îl vor mânca și vor lăuda pe Domnul."],[10,"Treci, treci pe porți!"],[11,"Iată, Domnul a vestit până la capătul pământului:"],[12,"Ei îi vor numi „Poporul Sfânt,"]]],[63,[[1,"Cine este acesta care vine din Edom,"],[2,"De ce hainele tale sunt roșii,"],[3,"„Am călcat singur teascul de vin."],[4,"Căci ziua răzbunării era în inima mea,"],[5,"M-am uitat și nu era nimeni care să ajute;"],[6,"Am călcat în picioare popoarele în mânia mea"],[7,"Voi spune despre bunătățile iubitoare ale Domnului"],[8,"Căci el a spus: „Cu siguranță, ei sunt poporul Meu,"],[9,"În toată suferința lor, el a fost chinuit,"],[10,"Dar s-au răzvrătit"],[11,"Apoi și-a amintit de zilele de odinioară,"],[12,"Cine a făcut ca brațul său glorios să fie la dreapta lui Moise?"],[13,"Care i-a condus prin adâncuri,"],[14,"Ca vitele care coboară în vale,"],[15,"Privește în jos din cer,"],[16,"Căci tu ești Tatăl nostru,"],[17,"O, Doamne, de ce ne faci să rătăcim din căile Tale,"],[18,"Poporul tău sfânt l-a stăpânit doar pentru puțin timp."],[19,"Am devenit ca cei peste care nu ai domnit niciodată,"]]],[64,[[1,"O, dacă ai rupe cerurile,"],[2,"ca atunci când focul aprinde tufișul,"],[3,"Când ai făcut lucruri minunate pe care noi nu le-am căutat,"],[4,"Căci din bătrâni n-au auzit,"],[5,"Îl întâlnești pe Cel ce se bucură și face dreptate,"],[6,"Căci toți am ajuns ca unul care este necurat,"],[7,"Nu este nimeni care să-ți cheme numele,"],[8,"Dar acum, Doamne, Tu ești Tatăl nostru."],[9,"Nu fi furios, Doamne."],[10,"Cetățile tale sfinte au devenit un pustiu."],[11,"Casa noastră sfântă și frumoasă unde te-au lăudat părinții noștri"],[12,"Te vei reține pentru aceste lucruri, Doamne?"]]],[65,[[1,"„Sunt întrebat de cei care nu au întrebat."],[2,"Mi-am întins mâinile toată ziua către un popor răzvrătit,"],[3,"un popor care mă provoacă neîncetat în fața mea,"],[4,"care stau printre morminte,"],[5,"care spun: „Stai singur,"],[6,"„Iată, este scris înaintea mea:"],[7,"propriile tale fărădelegi și fărădelegile părinților tăi împreună”, zice Domnul,"],[8,"Domnul spune,"],[9,"Voi scoate sămânță din Iacov,"],[10,"Sharon va fi o stâncă de turme,"],[11,"„Dar voi, care părăsiți pe Domnul,"],[12,"te voi destina sabiei,"],[13,"De aceea zice Domnul Domnul:"],[14,"Iată, slujitorii mei vor cânta de bucuria inimii,"],[15,"Îți vei lăsa numele pentru un blestem aleșilor mei,"],[16,"astfel încât cel ce se binecuvântează pe sine pe pământ se va binecuvânta în Dumnezeul adevărului;"],[17,"„Căci, iată, eu creez ceruri noi și un pământ nou;"],[18,"Dar bucurați-vă și bucurați-vă pentru totdeauna de ceea ce eu creez;"],[19,"Mă voi bucura în Ierusalim,"],[20,"„Nu va mai exista un copil care să trăiască doar câteva zile,"],[21,"Vor construi case și le vor locui."],[22,"Ei nu vor construi și altul locuiește."],[23,"Nu vor munci în zadar"],[24,"Se va întâmpla ca înainte ca ei să sune, să răspund;"],[25,"Lupul și mielul se vor hrăni împreună."]]],[66,[[1,"Domnul spune:"],[2,"Căci mâna mea a făcut toate aceste lucruri,"],[3,"Cel ce ucide un bou este ca cel care ucide un om;"],[4,"Voi alege și amăgirile lor,"],[5,"Ascultă cuvântul Domnului,"],[6,"Un glas de tumult din oraș,"],[7,"„Înainte de a avea nasterea, a născut."],[8,"Cine a auzit de așa ceva?"],[9,"Să aduc eu la naștere și să nu fac să nasc?” zice Domnul."],[10,"„Bucurați-vă împreună cu Ierusalimul și veseliți-vă pentru ea, toți cei ce o iubiți."],[11,"ca să alăptați și să vă mulțumiți de sânii mângâietori;"],[12,"Căci Domnul zice: „Iată, îi voi întinde pacea ca un râu,"],[13,"Ca unul pe care mama lui îl mângâie,"],[14,"Vei vedea și inima ta se va bucura,"],[15,"Căci, iată, Domnul va veni cu foc,"],[16,"Căci Domnul va face judecată prin foc și cu sabia Lui asupra oricărei făpturi;"],[17,"„Cei care se sfinţesc şi se curăţesc să meargă în grădini, urmând pe unul din mijloc, mâncând carne de porc, lucruri urâcioase şi şoarece, se vor sfârşi împreună”, zice Domnul."],[18,"„Căci le cunosc faptele și gândurile, vine vremea când voi aduna toate neamurile și toate limbile și vor veni și vor vedea slava Mea."],[19,"„Voi pune un semn printre ei și îi voi trimite pe cei scăpați dintre ei la neamuri, la Tarsis, Pul și Lud, care trag arcul, la Tubal și Javan, în insule îndepărtate, care n-au auzit faima Mea și n-au văzut slava Mea; și vor vesti slava Mea printre neamuri."],[20,"Îi vor aduce pe toți frații voștri din toate neamurile, ca jertfă Domnului, pe cai, în care, în litiere, pe catâri și pe cămile, pe muntele Meu sfânt, Ierusalim, zice Domnul, așa cum copiii lui Israel aduc darul lor într-un vas curat în casa Domnului."],[21,"Dintre ei voi alege și preoți și leviți”, zice Domnul."],[22,"„Căci precum cerurile noi și pământul nou, pe care le voi face, vor rămâne înaintea Mea”, zice Domnul, „așa vor rămâne sămânța și numele tău."],[23,"Se va întâmpla ca de la o lună nouă la alta și de la un Sabat la altul, orice făptură să vină să se închine înaintea Mea”, zice Domnul."],[24,"„Ei vor ieși și se vor uita la cadavrele oamenilor care au călcat împotriva Mea; căci viermele lor nu va muri, nici focul lor nu se va stinge și vor fi urâți de toată omenirea.”"]]]];